window.HEXAPLA_DATA=window.HEXAPLA_DATA||{};window.HEXAPLA_DATA["Habakkuk"]={"book":"Habakkuk","vol":2,"source":{"title":"Frederick Field, Origenis Hexaplorum quae supersunt, II (Oxford 1875)","url":"https://archive.org/details/origenhexapla02unknuoft","license":"public domain"},"verses":{"1:1":[{"s":0,"e":0,"h":"הַמַּשָּׂא","l":"_Vaticinium._","t":"Ο΄. Σ. Θ. τὸ λῆμμα. Ἀ. τὸ ἄρμα.^1","leaf":"1019","pg":"[1003]","fn":["1019.1.1"],"field":"1:1"}],"1:5":[{"s":0,"e":1,"h":"רְאוּ בַגּוֹיִם","l":"_Videte inter gentes._","t":"Ο΄. ἴδετε, οἱ καταφρονηταί (בֹּגְדִים). Ἀ. Σ. Θ. _aspicite in gentibus._ (S΄.) _videbitis calumniatores._ (Z΄.) _videbitis declinantes._^2","leaf":"1019","pg":"[1003]","fn":["1019.1.2"],"field":"1:5"},{"s":3,"e":4,"h":"וְהִתַּמְּהוּ תְּמָהוּ","l":"_Et obstupescite, obstupescite._","t":"Ο΄. καὶ θαυμάσατε (alia exempl. add. καὶ ἴδετε^3) θαυμάσια, ÷ καὶ ἀφανίσθητε ↙.^4","leaf":"1019","pg":"[1003]","fn":["1019.1.3","1019.1.4"],"field":"1:5"},{"s":5,"e":8,"h":"כִּי־פֹעַל פֹּעֵל בִּימֵיכֶם","l":"_Nam opus operans_ sum _in diebus vestris._","t":"Ο΄. διότι ἔργον ἐγὼ ἐργάζομαι ἐν ταῖς ἡμέραις ὑμῶν. Σ. διότι ἔργον ἐργασθήσεται ἐν ταῖς ἡμέραις ὑμῶν.^5","leaf":"1019","pg":"[1003]","fn":["1019.1.5"],"field":"1:5"}],"1:7":[{"s":3,"e":6,"h":"מִמֶּנּוּ מִשְׁפָּטוֹ וּשְׂאֵתוֹ יֵצֵא","l":"_Ab ipso judicium suum et dignitas sua proficiscitur._","t":"Ο΄. ἐξ αὐτοῦ τὸ κρίμα αὐτοῦ ἔσται, καὶ τὸ λῆμμα αὐτοῦ ἐξ αὐτοῦ ἐξελεύσεται. Σ. αὐτὸς ἑαυτῷ δικάσει, καὶ δόγματι ἑαυτοῦ ἐπεξελεύσεται.^6","leaf":"1019","pg":"[1003]","fn":["1019.1.6"],"field":"1:7"}],"1:8":[{"s":4,"e":5,"h":"מִזְּאֵבֵי עֶרֶב","l":"_Prae lupis vespertinis._","t":"Ο΄. ὑπὲρ τοὺς λύκους τῆς Ἀραβίας. Ἀ. παρὰ παρδάλεις τῆς ἑσπέρας.^7","leaf":"1019","pg":"[1003]","fn":["1019.1.7"],"field":"1:8"},{"s":6,"e":7,"h":"וּפָשׁוּ פָּרָשָׁיו","l":"_Et gestiunt equites ejus._","t":"Ο΄. καὶ ἐξιππάσονται οἱ ἱππεῖς αὐτοῦ. Σ. καὶ ἐκχυθήσονται οἱ ἱππεῖς αὐτοῦ.^8","leaf":"1019","pg":"[1003]","fn":["1019.1.8"],"field":"1:8"}],"1:9":[{"s":0,"e":5,"h":"כֻּלֹּה לְחָמָס יָבוֹא מְגַמַּת פְּנֵיהֶם קָדִימָה","l":"_Tota illa_ (gens) _ad vim_ inferendam _venit; turba_ (s. _desiderium_) _facierum eorum prorsum spectat._","t":"Ο΄. συντέλεια εἰς ἀσεβεῖς ἥξει, ἀνθεστηκότας προσώποις αὐτῶν ἐξεναντίας. Σ. πάντα εἰς πλεονεξίαν ἥξει, ἡ πρόσοψις τοῦ προσώπου αὐτῶν ἄνεμος καύσων.^9","leaf":"1019","pg":"[1003]","fn":["1019.1.9"],"field":"1:9"}],"1:10":[{"s":2,"e":2,"h":"יִתְקַלָּס","l":"_Irridebit._","t":"Ο΄. ἐντρυφήσει. Ἀ. _celebrabitur._ Σ. ἐμπαίξεται.^10","leaf":"1019","pg":"[1003]","fn":["1019.1.10"],"field":"1:10"},{"s":4,"e":5,"h":"מִשְׂחָק לוֹ","l":"_Ludibrio ei_ erunt.","t":"Ο΄. παίγνια αὐτοῦ. Ἀ. γελάσματα . . Σ. γέλως αὐτοῦ.^11","leaf":"1020","pg":"1004","fn":["1020.0.11"],"field":"1:10"}],"1:11":[{"s":4,"e":4,"h":"וְאָשֵׁם","l":"_Et delinquet._","t":"Ο΄. καὶ ἐξιλάσεται. Ἀ. Σ. καὶ πλημμελήσει.^12","leaf":"1020","pg":"1004","fn":["1020.0.12"],"field":"1:11"}],"1:12":[{"s":0,"e":7,"h":"הֲלוֹא אַתָּה מִקֶּדֶם יְהֹוָה אֱלֹהַי קְדֹשִׁי לֹא נָמוּת","l":"_Nonne tu ab antiquo_ es, _Deus meus, Sanctus meus? non moriemur._","t":"Ο΄. οὐχὶ σὺ ἀπ᾽ ἀρχῆς, κύριε ὁ θεὸς ὁ ἅγιός μου; καὶ οὐ μὴ ἀποθάνωμεν. Σ. οὐχὶ σὺ ἀπ᾽ ἀρχῆς, κύριε ὁ θεός μου ὁ ἅγιός μου, ἵνα μὴ ἀποθάνωμεν;^13","leaf":"1020","pg":"1004","fn":["1020.0.13"],"field":"1:12"},{"s":8,"e":13,"h":"יְהֹוָה לְמִשְׁפָּט שַׂמְתּוֹ וְצוּר לְהוֹכִיחַ יְסַדְתּוֹ","l":"_O Jova, ad judicium posuisti eum, et, O rupes, ad castigandum constituisti eum._","t":"Ο΄. κύριε, εἰς κρίμα τέταχας αὐτὸ, καὶ ἔπλασέ με τοῦ ἐλέγχειν παιδείαν αὐτοῦ. Ἀ. . . καὶ στερεὸν εἰς τὸ ἐλέγχειν ἐθεμελίωσας αὐτόν.^14 Σ. κύριε, εἰς τὸ κρίνειν ἔταξας αὐτὸν, κραταιὸν εἰς τὸ ἐλέγχειν ἔστησας αὐτόν.^15","leaf":"1020","pg":"1004","fn":["1020.0.14","1020.0.15"],"field":"1:12"}],"1:13":[{"s":0,"e":8,"h":"טְהוֹר עֵינַיִם מֵרְאוֹת רָע וְהַבִּיט אֶל־עָמָל לֹא תוּכָל","l":"_Mundior_ es _oculis,_ quam _ut videas malum, et intueri_ (patienter ferre) _aerumnam non potes._","t":"Ο΄. καθαρὸς ὁ ὀφθαλμὸς τοῦ μὴ ὁρᾶν πονηρὰ, καὶ ἐπιβλέπειν ἐπὶ πόνους ὀδύνης (alia exempl. οὐ δυνήσῃ^16). Σ. καθαρὸς εἶ τοὺς ὀφθαλμοὺς ὥστε μὴ ὁρᾶν τὸ κακὸν, καὶ βλέπειν πρὸς μόχθον οὐκ ἀνεχόμενος.^17","leaf":"1020","pg":"1004","fn":["1020.0.16","1020.0.17"],"field":"1:13"},{"s":12,"e":16,"h":"תַּחֲרִישׁ בְּבַלַּע רָשָׁע צַדִּיק מִמֶּנּוּ","l":"_Taceas cum devorat impius justiorem se?_","t":"Ο΄. παρασιωπήσῃ ἐν τῷ καταπίνειν ἀσεβῆ τὸν δίκαιον (alia exempl. add. ὑπὲρ αὐτόν^18). Ἀ. Σ. Θ. παρασιωπᾷς καταπίνοντος ἀσεβοῦς τὸν δικαιότερον αὐτοῦ.^19","leaf":"1020","pg":"1004","fn":["1020.0.18","1020.0.19"],"field":"1:13"}],"1:15":[{"s":10,"e":10,"h":"וְיָגִיל","l":"_Et exsultat._","t":"Ο΄. καὶ χαρήσεται [ἡ καρδία αὐτοῦ].^20","leaf":"1020","pg":"1004","fn":["1020.0.20"],"field":"1:15"}],"1:17":[{"s":2,"e":3,"h":"יָרִיק חֶרְמוֹ","l":"_Evacuabit sagenam suam._","t":"Ο΄. ἀμφιβαλεῖ τὸ ἀμφίβληστρον αὐτοῦ. Ἄλλος· ἐκκενώσει μάχαιραν αὐτοῦ (חַרְבּוֹ).^21","leaf":"1020","pg":"1004","fn":["1020.0.21"],"field":"1:17"}],"2:1":[{"s":0,"e":14,"h":"עַל־מִשְׁמַרְתִּי אֶעֱמֹדָה וְאֶתְיַצְּבָה עַל־מָצוֹר וַאֲצַפֶּה לִרְאוֹת מַה־יְדַבֶּר־בִּי וּמָה אָשִׁיב עַל־תּוֹכַחְתִּי","l":"_In specula mea stabo, et sistam me in munimento; et speculabor ut videam quid locuturus sit mecum, et quid respondeam super disputatione mea._","t":"Ο΄. ἐπὶ τῆς φυλακῆς μου στήσομαι, καὶ ἐπιβήσομαι ἐπὶ πέτραν (Ἀ. Ε΄. _circinum._ Σ. _conclusus._ Θ. γῦρον^1), καὶ ἀποσκοπεύσω τοῦ ἰδεῖν τί λαλήσει ἐν ἐμοὶ, καὶ τί ἀποκριθῶ ἐπὶ τὸν ἔλεγχόν μου. Σ. ὡς φύλαξ ἐπὶ τῆς σκοπιᾶς μου στήσομαι, _et stabo velut inclusus, et contemplabor ut videam quid dicatur mihi, et quid respondeam et contradicam adversum arguentem me._^2","leaf":"1020","pg":"1004","fn":["1020.1.1","1020.1.2"],"field":"2:1"}],"2:2":[{"s":4,"e":4,"h":"חָזוֹן","l":"","t":"Ο΄. ὅρασιν. Ἀ. ὁραματισμόν.^3","leaf":"1020","pg":"1004","fn":["1020.1.3"],"field":"2:2"},{"s":6,"e":7,"h":"עַל־הַלֻּחוֹת","l":"_Super tabulis._","t":"Ο΄. εἰς πυξίον. Σ. ἐπὶ σελίδων.^4","leaf":"1020","pg":"1004","fn":["1020.1.4"],"field":"2:2"},{"s":9,"e":9,"h":"יָרוּץ","l":"_Currat._","t":"Ο΄. διώκῃ. Ἀ. Σ. τρέχῃ.^5","leaf":"1021","pg":"1005","fn":["1021.0.5"],"field":"2:2"}],"2:3":[{"s":6,"e":7,"h":"וְלֹא יְכַזֵּב","l":"_Et non mentietur._","t":"Ο΄. καὶ οὐκ εἰς κενόν. Ἀ. Σ. καὶ οὐ διαψεύσεται.^6","leaf":"1021","pg":"1005","fn":["1021.0.6"],"field":"2:3"},{"s":8,"e":16,"h":"אִם־יִתְמַהְמָהּ חַכֵּה־לוֹ כִּי־בֹא יָבֹא לֹא יְאַחֵר","l":"_Si moratur, exspecta eam; nam certissime veniet, non cunctabitur._","t":"Ο΄. ἐὰν ὑστερήσῃ, ὑπόμεινον αὐτὸν, ὅτι ἐρχόμενος ἥξει, καὶ οὐ μὴ χρονίσῃ. Ἀ. ἐὰν [δὲ] μελλήσῃ, προσδέχου αὐτὸν, ὅτι ἐρχόμενος ἥξει (s. ἐλεύσεται), καὶ οὐ βραδυνεῖ.^7 Σ. (ἐὰν) στραγγεύσηται . . .^8","leaf":"1021","pg":"1005","fn":["1021.0.7","1021.0.8"],"field":"2:3"}],"2:4":[{"s":0,"e":5,"h":"הִנֵּה עֻפְּלָה לֹא־יָשְׁרָה נַפְשׁוֹ בּוֹ","l":"_Ecce!_ quae _effert se, non recta est anima ejus in eo._","t":"Ο΄. ἐὰν ὑποστείληται, οὐκ εὐδοκεῖ ἡ ψυχή μου ἐν αὐτῷ. Ἀ. ἰδοὺ νωχελευομένου οὐκ εὐθεῖα ἡ ψυχή μου ἐν αὐτῷ.^9","leaf":"1021","pg":"1005","fn":["1021.0.9"],"field":"2:4"},{"s":6,"e":8,"h":"וְצַדִּיק בֶּאֱמוּנָתוֹ יִחְיֶה","l":"_Sed justus per fidem suam vivet._","t":"Ο΄. ὁ δὲ δίκαιος ἐκ πίστεώς μου (Πάντες· αὐτοῦ^10) ζήσεται. Ἀ. καὶ δίκαιος ἐν πίστει αὐτοῦ ζήσεται.^11 Σ. ὁ (δὲ) δίκαιος τῇ ἑαυτοῦ πίστει ζήσει.^12","leaf":"1021","pg":"1005","fn":["1021.0.10","1021.0.11","1021.0.12"],"field":"2:4"}],"2:5":[{"s":6,"e":7,"h":"וְלֹא יִנְוֶה","l":"_Nec quiescit._","t":"Ο΄. οὐθὲν μὴ περάνῃ. Σ. οὐκ εὐπραγήσει.^13 Aliter: Σ. οὐκ εὐπορήσει.^14","leaf":"1021","pg":"1005","fn":["1021.0.13","1021.0.14"],"field":"2:5"}],"2:6":[{"s":0,"e":8,"h":"הֲלוֹא־אֵלֶּה כֻלָּם עָלָיו מָשָׁל יִשָּׂאוּ וּמְלִיצָה חִידוֹת לוֹ","l":"_Nonne isti omnes de eo carmen irrisorium tollent, et dicterium,_ et _aenigmata in eum?_","t":"Ο΄. οὐχὶ ταῦτα πάντα κατ᾽ αὐτοῦ παραβολὴν λήψονται, καὶ πρόβλημα εἰς διήγησιν αὐτοῦ; Σ. μὴ οὐχὶ ταῦτα πάντα περὶ αὐτοῦ εἰς παραβολὴν ληφθήσεται, καὶ αἴνιγμα προβλήματος κατ᾽ αὐτοῦ;^15","leaf":"1021","pg":"1005","fn":["1021.0.15"],"field":"2:6"}],"2:7":[{"s":2,"e":2,"h":"יָקוּמוּ","l":"_Surgent._","t":"Ο΄. ἀναστήσονται. Θ. ἐξεγερθήσονται.^16","leaf":"1021","pg":"1005","fn":["1021.0.16"],"field":"2:7"},{"s":4,"e":4,"h":"וְיִקְצוּ","l":"_Et evigilabunt._","t":"Ο΄. καὶ ἐκνήψουσιν. Οἱ λοιποί· ἐξυπνισθήσονται.^17","leaf":"1021","pg":"1005","fn":["1021.0.17"],"field":"2:7"}],"2:8":[{"s":14,"e":16,"h":"וְכָל־יֹשְׁבֵי בָהּ","l":"","t":"Ο΄. ※ Ἀ. Θ. καὶ ↙ πάντων τῶν κατοικούντων αὐτήν.^18","leaf":"1021","pg":"1005","fn":["1021.0.18"],"field":"2:8"}],"2:9":[{"s":0,"e":0,"h":"הוֹי","l":"","t":"Ο΄. ὦ. Σ. οὐαί.^19","leaf":"1021","pg":"1005","fn":["1021.0.19"],"field":"2:9"}],"2:11":[{"s":0,"e":6,"h":"כִּי־אֶבֶן מִקִּיר תִּזְעָק וְכָפִיס מֵעֵץ יַעֲנֶנָּה","l":"_Nam lapis e pariete clamat, et canterius_ (tignum transversum) _e ligno respondet ei._","t":"Ο΄. διότι λίθος ἐκ τοίχου βοήσεται, καὶ κάνθαρος ἐκ ξύλου φθέγξεται αὐτά. Ἀ. . . καὶ μάζα ἐκ ξύλου ἀποκριθήσεται.^20 Σ. . . καὶ σύνδεσμος οἰκοδομῆς ξύλινος ἀποφθέγξεται αὐτά.^21 Θ. Ε΄. . . καὶ σύνδεσμος (s. ἔνδεσμος) ξύλου φθέγξεται αὐτά.^22 (S΄.) _Quia lapis de pariete clamabit,_","leaf":"1021","pg":"1005","fn":["1021.0.20","1021.0.21","1021.0.22"],"field":"2:11"},{"s":0,"e":6,"h":"כִּי־אֶבֶן מִקִּיר תִּזְעָק וְכָפִיס מֵעֵץ יַעֲנֶנָּה","l":"","t":"_quasi vermis in ligno loquens._ (Z΄.) _Lapis enim de pariete vociferabitur, et_ σκώληξ _de ligno loquetur ea._^23","leaf":"1022","pg":"1006","fn":["1022.0.23"],"field":"2:11","cont":true}],"2:14":[{"s":8,"e":10,"h":"יְכַסּוּ עַל־יָם","l":"_Operiunt mare._","t":"Ο΄. κατακαλύψει αὐτούς. Alia exempl. κατακαλύψαι θαλάσσας.^24","leaf":"1022","pg":"1006","fn":["1022.0.24"],"field":"2:14"}],"2:15":[{"s":0,"e":4,"h":"הוֹי מַשְׁקֵה רֵעֵהוּ מְסַפֵּחַ חֲמָתְךָ","l":"_Vae_ illi, _qui potum dat socio suo,_ (tibi, inquam) _qui infundis fervorem_ (fervidum vinum) _tuum._","t":"Ο΄. ὦ ὁ ποτίζων τὸν πλησίον αὐτοῦ ἀνατροπῇ θολερᾷ. Ἀ. . . ἐξ ἐπιρρίψεως χόλου σου.^25 Σ. . . καὶ ἀφιῶν ἀκρίτως τὸν θυμὸν ἑαυτοῦ.^26 Θ. . . ἀπὸ χύσεώς σου.^27 Ε΄. . . ἐξ ἀπροσδοκήτου ἀνατροπῆς τῆς ὀργῆς σου.^28 Ἄλλος· οὐαὶ τῷ ποτίζοντι τὸν ἑταῖρον αὐτοῦ ἄελλαν πετομένην.^29 Ἄλλος· οὐαὶ τῷ ποτίζοντι τὸν πλησίον αὐτοῦ ἔκστασιν ὀχλουμένην.^30","leaf":"1022","pg":"1006","fn":["1022.0.25","1022.0.26","1022.0.27","1022.0.28","1022.0.29","1022.0.30"],"field":"2:15"},{"s":9,"e":10,"h":"עַל־מְעוֹרֵיהֶם","l":"_Super pudenda eorum._","t":"Ο΄. ἐπὶ τὰ σπήλαια (Ἀ. γύμνωσιν. Σ. ἀσχημοσύνην^31) αὐτῶν.","leaf":"1022","pg":"1006","fn":["1022.0.31"],"field":"2:15"}],"2:16":[{"s":6,"e":6,"h":"וְהֵעָרֵל","l":"_Et praeputiatum siste te._","t":"Ο΄. καρδία σαλεύθητι (alia exempl. καὶ διασαλεύθητι^32) καὶ σείσθητι. Ἀ. καὶ καρώθητι.^33","leaf":"1022","pg":"1006","fn":["1022.0.32","1022.0.33"],"field":"2:16"}],"2:17":[{"s":1,"e":1,"h":"חֲמַס","l":"_Violentia._","t":"Ο΄. ἀσέβεια. Ἀ. αἷμα. Σ. πλεονεξίαν.^34","leaf":"1022","pg":"1006","fn":["1022.0.34"],"field":"2:17"},{"s":4,"e":5,"h":"וְשֹׁד בְּהֵמוֹת","l":"_Et vastatio bestiarum._","t":"Ο΄. καὶ ταλαιπωρία θηρίων. Ἀ. καὶ προνομὴ κτηνῶν. Σ. (καὶ) διαρπαγὴ κτητῶν.^35","leaf":"1022","pg":"1006","fn":["1022.0.35"],"field":"2:17"},{"s":6,"e":6,"h":"יְחִיתַן","l":"Quae _terruit eas._","t":"Ο΄. πτοήσει σε. Ἀ. καταπτήξει. Σ. ἡττήσει.^36","leaf":"1022","pg":"1006","fn":["1022.0.36"],"field":"2:17"}],"2:18":[{"s":5,"e":5,"h":"יֹצְרוֹ","l":"_Fictor ejus._","t":"Ο΄. ἔπλασεν (alia exempl. ἔπλασαν^37) αὐτό. Θ. πλάσσων.^38","leaf":"1022","pg":"1006","fn":["1022.0.37","1022.0.38"],"field":"2:18"},{"s":16,"e":16,"h":"אִלְּמִים","l":"(Idola) _muta._","t":"Ο΄. κωφά. Σ. ἄλαλα.^39","leaf":"1022","pg":"1006","fn":["1022.0.39"],"field":"2:18"}],"2:19":[{"s":14,"e":17,"h":"וְכָל־רוּחַ אֵין בְּקִרְבּוֹ","l":"_Et omnis spiritus non est in medio ejus._","t":"Ο΄. καὶ πᾶν πνεῦμα οὐκ ἔστιν ἐν αὐτῷ (Ἀ. ἐν ἐγκάτοις αὐτοῦ^40).","leaf":"1022","pg":"1006","fn":["1022.0.40"],"field":"2:19"}],"3:1":[{"s":3,"e":4,"h":"עַל שִׁגְיֹנוֹת","l":"_Ad modum carminum dithyrambicorum._","t":"Ο΄. μετὰ ᾠδῆς. Ἀ. Σ. Ε΄. ἐπὶ ἀγνοη-","leaf":"1022","pg":"1006","fn":[],"field":"3:1"},{"s":3,"e":4,"h":"עַל שִׁגְיֹנוֹת","l":"","t":"μάτων. Θ. ὑπὲρ τῶν ἑκουσιασμῶν (fort. ἀκουσιασμῶν).^1","leaf":"1023","pg":"1007","fn":["1023.1.1"],"field":"3:1","cont":true}],"3:2":[{"s":3,"e":3,"h":"יָרֵאתִי","l":"_Timui._","t":"Ο΄. καὶ ἐφοβήθην. Ἄλλος· καὶ εὐλαβήθην.^2","leaf":"1023","pg":"1007","fn":["1023.1.2"],"field":"3:2"},{"s":4,"e":8,"h":"יְהֹוָה פָּעָלְךָ בְּקֶרֶב שָׁנִים חַיֵּיהוּ","l":"_Jova, opus tuum in medio annorum vivifica_ (exsequere).","t":"Ο΄. κατενόησα (alia exempl. κύριε, κατενόησα^3) τὰ ἔργα σου, καὶ ἐξέστην· ἐν μέσῳ δύο ζώων γνωσθήσῃ.^4 Ἀ. . . ἐν τῷ ἐγγίζειν τὰ ἔτη ζώωσον αὐτό. Σ. . . ἐντὸς τῶν ἐνιαυτῶν ἀναζώωσον αὐτόν. Θ. ἐν μέσῳ ἐτῶν ζώωσον αὐτόν.^5","leaf":"1023","pg":"1007","fn":["1023.1.3","1023.1.4","1023.1.5"],"field":"3:2"},{"s":9,"e":11,"h":"בְּקֶרֶב שָׁנִים תּוֹדִיעַ","l":"_In medio annorum notum facias._","t":"Ο΄. ἐν τῷ ἐγγίζειν τὰ ἔτη ἐπιγνωσθήσῃ· ÷ ἐν τῷ παρεῖναι τὸν καιρὸν ἀναδειχθήσῃ· ἐν τῷ ταραχθῆναι τὴν ψυχήν μου ↙.^6","leaf":"1023","pg":"1007","fn":["1023.1.6"],"field":"3:2"}],"3:3":[{"s":0,"e":5,"h":"אֱלוֹהַּ מִתֵּימָן יָבוֹא וְקָדוֹשׁ מֵהַר־פָּארָן","l":"_Deus e Theman venit, et Sanctus e monte Pharan._","t":"Ο΄. ὁ θεὸς ἐκ Θαιμὰν (Ἄλλος· ἀπὸ λιβὸς^7) ἥξει, καὶ ὁ ἅγιος ἐξ ὄρους [Φαρὰν] κατασκίου δασέος (Ἀ. Σ. Θ. Φαράν^8). Ἀ. Σ. Ε΄. ὁ θεὸς ἐκ Θαιμὰν ἥξει . . . Θ. Ἐλωεὶμ ἀπὸ νοτίου (s. νότου) ἥξει, καὶ ὁ ἅγιος ἐξ ὄρους Φαράν.^9","leaf":"1023","pg":"1007","fn":["1023.1.7","1023.1.8","1023.1.9"],"field":"3:3"},{"s":6,"e":6,"h":"סֶלָה","l":"","t":"Ο΄. διάψαλμα. Σ. εἰς τὸν αἰῶνα. Θ. εἰς τέλος. Ε΄. σελά.^10 Ἄλλος· μεταβολὴ διαψάλματος.^11","leaf":"1023","pg":"1007","fn":["1023.1.10","1023.1.11"],"field":"3:3"},{"s":7,"e":12,"h":"כִּסָּה שָׁמַיִם הוֹדוֹ וּתְהִלָּתוֹ מָלְאָה הָאָרֶץ","l":"_Operuit caelum majestas ejus, et laude ejus repleta est terra._","t":"Ο΄. ἐκάλυψεν οὐρανοὺς ἡ ἀρετὴ αὐτοῦ, καὶ αἰνέσεως αὐτοῦ πλήρης ἡ γῆ. Ἀ. Θ. ἀπεκάλυψεν οὐρανοὺς τὴν εὐπρέπειαν αὐτῆς, δόξης αὐτοῦ καὶ τῆς αἰνέσεως αὐτοῦ ἐπληρώθη ἡ οἰκουμένη.^12 Ἄλλος· ἐκάλυψεν ὁ","leaf":"1023","pg":"1007","fn":["1023.1.12"],"field":"3:3"},{"s":7,"e":12,"h":"כִּסָּה שָׁמַיִם הוֹדוֹ וּתְהִלָּתוֹ מָלְאָה הָאָרֶץ","l":"","t":"οὐρανὸς τὴν εὐπρέπειαν τῆς δόξης αὐτοῦ, καὶ τῆς αἰνέσεως αὐτοῦ ἐπλήσθη ἡ οἰκουμένη.^13","leaf":"1024","pg":"1008","fn":["1024.0.13"],"field":"3:3","cont":true}],"3:4":[{"s":0,"e":5,"h":"וְנֹגַהּ כָּאוֹר תִּהְיֶה קַרְנַיִם מִיָּדוֹ לוֹ","l":"_Et splendor instar lucis_ (solis) _erat; radii e manu ejus_ erant _ei._","t":"Ο΄. καὶ φέγγος αὐτοῦ ὡς φῶς ἔσται· κέρατα ἐν χερσὶν αὐτοῦ. Ἄλλος· διαύγασμα φωτὸς ἔσται αὐτῷ· κέρατα ἐκ χειρὸς αὐτοῦ ὑπάρχει αὐτῷ.^14","leaf":"1024","pg":"1008","fn":["1024.0.14"],"field":"3:4"},{"s":6,"e":8,"h":"וְשָׁם חֶבְיוֹן עֻזֹּה","l":"_Et ibi_ erat _latibulum roboris ejus._","t":"Ο΄. καὶ ἔθετο ἀγάπησιν κραταιὰν ἰσχύος αὐτοῦ. Ἀ. καὶ ἔθετο ἀποκρυφὴν ἰσχύος αὐτοῦ. Σ. καὶ ἔθετο κεκρυμμένην ἰσχὺν αὐτοῦ. Θ. καὶ ἐκεῖ ἀποκρυφὴ ἰσχύος αὐτοῦ.^15 Ἄλλος· ἐκεῖ ἐπεστήρικται ἡ δύναμις τῆς δόξης αὐτοῦ.^16","leaf":"1024","pg":"1008","fn":["1024.0.15","1024.0.16"],"field":"3:4"}],"3:5":[{"s":0,"e":2,"h":"לְפָנָיו יֵלֶךְ דָּבֶר","l":"_Ante eum ibat pestis._","t":"Ο΄. πρὸ προσώπου αὐτοῦ πορεύσεται λόγος (Θ. λόγος). Ἀ. πρὸ προσώπου αὐτοῦ πορεύσεται λοιμός. Σ. πρὸ προσώπου αὐτοῦ προπορεύσεται θάνατος. Ε΄. πρὸ προσώπου αὐτοῦ περιπατήσει θάνατος.^17 Ἄλλος· πρὸ προσώπου αὐτοῦ προελεύσεται πτῶσις.^18","leaf":"1024","pg":"1008","fn":["1024.0.17","1024.0.18"],"field":"3:5"},{"s":3,"e":5,"h":"וְיֵצֵא רֶשֶׁף לְרַגְלָיו","l":"_Et egressa est febris ardens ad pedes ejus._","t":"Ο΄. καὶ ἐξελεύσεται εἰς πεδία (Ἀ. πτηνόν. Σ. Θ. Ε΄. πετεινὸν^19) κατὰ πόδας αὐτοῦ. Ἄλλος· καὶ κατὰ πόδας αὐτοῦ ἀκολουθήσει τὰ μέγιστα τῶν πετεινῶν.^20","leaf":"1024","pg":"1008","fn":["1024.0.19","1024.0.20"],"field":"3:5"}],"3:6":[{"s":0,"e":14,"h":"עָמַד וַיְמֹדֶד אֶרֶץ רָאָה וַיַּתֵּר גּוֹיִם וַיִּתְפֹּצְצוּ הַרְרֵי־עַד שַׁחוּ גִּבְעוֹת עוֹלָם הֲלִיכוֹת עוֹלָם לוֹ","l":"_Stetit, et mensus est_ (s. _commovit_) _terram; vidit, et trepidare fecit gentes; et dissiluerunt montes sempiterni, depressi sunt colles aeterni; viae antiquae_ sunt _ei._","t":"Ο΄. ἔστη, καὶ ἐσαλεύθη ἡ γῆ· ἐπέβλεψε, καὶ διετάκη ἔθνη· διεθρύβη τὰ ὄρη βίᾳ· ἐτάκησαν βουνοὶ αἰώνιοι πορείας αἰωνίας αὐτοῦ. Ἄλλος· στὰς διεμέτρησε τὴν γῆν· κατανοήσας ἐξείκασε τὰ ἔθνη· διεθρύβη, καὶ τὰ ὄρη θραυσθήσεται· ταπεινωθήσονται αἱ νάπαι (αἱ) ἐκ τοῦ αἰῶνος· αἱ ὁδοὶ αἱ ἐξ ἀρχῆς ἀλλοιωθήσονται· αὐτοῦ ἕνεκα σεισθήσεται ἡ οἰκουμένη.^21","leaf":"1024","pg":"1008","fn":["1024.0.21"],"field":"3:6"}],"3:7":[{"s":0,"e":8,"h":"תַּחַת אָוֶן רָאִיתִי אָהֳלֵי כוּשָׁן יִרְגְּזוּן יְרִיעוֹת אֶרֶץ מִדְיָן","l":"_Sub aerumna vidi tentoria Chusan; trepidaverunt aulaea terrae Midian._","t":"Ο΄. ἀντὶ κόπων εἶδον σκηνώματα Αἰθιόπων· πτοηθήσονται καὶ αἱ σκηναὶ γῆς Μαδιάμ. Ἄλλος· κατανενόηκα τὰς σκηνὰς Αἰθιόπων· ταραχθήσονται οἱ κατοικοῦντες τὰς δέρρεις Μαδιάμ.^22","leaf":"1024","pg":"1008","fn":["1024.0.22"],"field":"3:7"}],"3:8":[{"s":6,"e":14,"h":"אִם־בַּיָּם עֶבְרָתֶךָ כִּי תִרְכַּב עַל־סוּסֶיךָ מַרְכְּבֹתֶיךָ יְשׁוּעָה","l":"_Num in mare indignatio tua, quod conscendisti equos tuos, currus tuos salutis?_","t":"Ο΄. ἢ ἐν θαλάσσῃ τὸ ὅρμημά σου, ὅτι ἐπιβήσῃ ἐπὶ τοὺς ἵππους σου, καὶ ἡ ἱππασία σου σωτηρία; Ἄλλος· ἢ ἐν θαλάσσῃ ἡ ὀργή σου;","leaf":"1024","pg":"1008","fn":[],"field":"3:8"},{"s":6,"e":14,"h":"אִם־בַּיָּם עֶבְרָתֶךָ כִּי תִרְכַּב עַל־סוּסֶיךָ מַרְכְּבֹתֶיךָ יְשׁוּעָה","l":"","t":"ἀνέβης ἐπὶ τὰ ἅρματά σου· ἡ ἱππασία σου σωτηρία.^23","leaf":"1025","pg":"1009","fn":["1025.0.23"],"field":"3:8","cont":true}],"3:9":[{"s":0,"e":5,"h":"עֶרְיָה תֵעוֹר קַשְׁתֶּךָ שְׁבֻעוֹת מַטּוֹת אֹמֶר","l":"_Nudatione nudatur arcus tuus; jurajuranda sunt virgae verbi_ (jurejurando firmatae sunt castigationes a Deo annuntiatae).","t":"Ο΄. ἐντείνων ἐνέτεινας τόξον σου ἐπὶ σκῆπτρα, λέγει ÷ κύριος ↙.^24 Ἄλλος· ὃ προέβης ἐξηγέρθη τὸ τόξον σου, ἐχόρτασας βολίδας τῆς φαρέτρας αὐτῆς.^25","leaf":"1025","pg":"1009","fn":["1025.0.24","1025.0.25"],"field":"3:9"},{"s":7,"e":9,"h":"נְהָרוֹת תְּבַקַּע־אָרֶץ","l":"_Fluminibus fidisti terram._","t":"Ο΄. ποταμῶν ῥαγήσεται γῆ. Ἄλλος· ποταμοὺς διασκεδάσεις, καὶ γῆν σείσεις.^26","leaf":"1025","pg":"1009","fn":["1025.0.26"],"field":"3:9"}],"3:10":[{"s":0,"e":11,"h":"רָאוּךָ יָחִילוּ הָרִים זֶרֶם מַיִם עָבָר נָתַן תְּהוֹם קוֹלוֹ רוֹם יָדֵיהוּ נָשָׂא","l":"_Viderunt te, contremuerunt montes; imber aquarum transiit; edidit abyssus vocem suam; in altum manus suas sustulit._","t":"Ο΄. ὄψονταί σε, καὶ ὠδινήσουσι λαοὶ, σκορπίζων ὕδατα πορείας (Οἱ λοιποί· _illisio,_ vel _impetus, aquarum transiet_^27)· ἔδωκεν ἡ ἄβυσσος φωνὴν αὐτῆς, ὕψος φαντασίας αὐτῆς. ἐπήρθη. Ἄλλος· ἐν τῷ ἀντοφθαλμεῖν σε ταραχθήσονται τὰ ὄρη· ἐν τῷ τὸν ἐξαίσιόν σου ὄμβρον διελθεῖν δι’ αὐτῆς, ἡ ἄβυσσος ἀνεφώνησε μεῖζον.^28","leaf":"1025","pg":"1009","fn":["1025.0.27","1025.0.28"],"field":"3:10"}],"3:11":[{"s":0,"e":9,"h":"שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה לְאוֹר חִצֶּיךָ יְהַלֵּכוּ לְנֹגַהּ בְּרַק חֲנִיתֶךָ","l":"_Sol_ cum _luna stetit in domicilio suo; ad lucem sagittarum tuarum incedebant, ad splendorem fulguris hastae tuae._","t":"Ο΄. (ἐπήρθη) ὁ ἥλιος, καὶ ἡ σελήνη ἔστη ἐν τῇ τάξει αὐτῆς· εἰς φῶς βολίδες σου πορεύσονται, εἰς φέγγος ἀστραπῆς ὅπλων σου (Ἀ. Σ. δόρατός σου. Θ. λόγχη σου^29). Ἄλλος· φῶς τὸ λαμπρὸν τοῦ ἡλίου ἐπέσχεν· τὸ δὲ φέγγος τῆς σελήνης ἐστάθη· κατὰ τὸ φέγγος τῶν βολίδων σου πορεύσονται, κατὰ τὸ φέγγος ἀστραπῆς μαχαίρας σου.^30","leaf":"1025","pg":"1009","fn":["1025.0.29","1025.0.30"],"field":"3:11"}],"3:12":[{"s":0,"e":5,"h":"בְּזַעַם תִּצְעַד־אָרֶץ בְּאַף תָּדוּשׁ גּוֹיִם","l":"_Cum indignatione gressus es per terram, cum ira triturasti gentes._","t":"Ο΄. ἐν ἀπειλῇ ὀλιγώσεις (alia exempl. συμπατήσεις^31) γῆν, καὶ ἐν θυμῷ κατάξεις ἔθνη. Ἄλλος· μετὰ θυμοῦ ἐγερθήσῃ ἐπὶ τὴν γῆν, μετ’ ὀργῆς ἀλοήσεις ἔθνη.^32","leaf":"1025","pg":"1009","fn":["1025.0.31","1025.0.32"],"field":"3:12"}],"3:13":[{"s":0,"e":5,"h":"יָצָאתָ לְיֵשַׁע עַמֶּךָ לְיֵשַׁע אֶת־מְשִׁיחֶךָ","l":"_Egressus es ad liberandum populum tuum, ad liberandum Unctum tuum._","t":"Ο΄. ἐξῆλθες εἰς σωτηρίαν λαοῦ σου, τοῦ σῶσαι τὸν χριστόν (alia exempl. τοὺς χριστούς^33) σου. Ἀ. Ε΄. ἐξῆλθες εἰς σωτηρίαν λαοῦ σου, εἰς σωτηρίαν σὺν χριστῷ σου.^34 Σ. ἐξῆλθες τοῦ σῶσαι τὸν λαόν σου, τοῦ σῶσαι τὸν χριστόν σου. Θ. ἐξῆλθες εἰς σωτηρίαν λαοῦ σου, τοῦ σῶσαι τὸν χριστόν σου.^35 S΄. ἐξῆλθες τοῦ σῶσαι τὸν λαόν","leaf":"1025","pg":"1009","fn":["1025.0.33","1025.0.34","1025.0.35"],"field":"3:13"},{"s":0,"e":5,"h":"יָצָאתָ לְיֵשַׁע עַמֶּךָ לְיֵשַׁע אֶת־מְשִׁיחֶךָ","l":"","t":"σου διὰ Ἰησοῦν τὸν χριστόν σου (potius διὰ Ἰησοῦ τοῦ χριστοῦ σου).^36 Ἄλλος· ἀνεφάνης ἐπὶ σωτηρίᾳ τοῦ λαοῦ σου, ῥύσασθαι τοὺς ἐκλεκτούς σου.^37","leaf":"1026","pg":"1010","fn":["1026.0.36","1026.0.37"],"field":"3:13","cont":true},{"s":6,"e":14,"h":"מָחַצְתָּ ראשׁ מִבֵּית רָשָׁע עָרוֹת יְסוֹד עַד־צַוָּאר סֶלָה","l":"_Percussisti caput de domo impii, nudando fundamentum usque ad collum. Selah._","t":"Ο΄. βαλεῖς (alia exempl. ἔβαλες^38) εἰς κεφαλὰς ἀνόμων θάνατον· ἐξήγειρας δεσμοὺς ἕως τραχήλου. διάψαλμα (alia exempl. εἰς τέλος; alia, εἰς τέλος. διάψαλμα^39). Θ. . . ἐκόσμησας θεμέλιον ἕως τραχήλου . . Ε΄. . . ἐξεκένωσας θεμέλιον ἕως τραχήλου . .^40 Ἄλλος· κατετόξευσας κεφαλὰς ἀνθρώπων ὑπερηφάνων· ἕως ἀβύσσου τῆς θαλάσσης καταδύσονται.^41","leaf":"1026","pg":"1010","fn":["1026.0.38","1026.0.39","1026.0.40","1026.0.41"],"field":"3:13"}],"3:15":[{"s":0,"e":5,"h":"דָּרַכְתָּ בַיָּם סוּסֶיךָ חֹמֶר מַיִם רַבִּים","l":"_Calcasti in mari equis tuis, in luto_ (s. _acervo_) _aquarum multarum._","t":"Ο΄. καὶ ἐπιβιβᾷς (alia exempl. ἐπεβίβασας^44) εἰς θάλασσαν τοὺς ἵππους σου, ταράσσοντας ὕδωρ πολύ. Ἄλλος· ἀνεβίβασας ἐπὶ θαλάσσας τοὺς ἵππους σου· ἐταράχθη τὰ ἐξαίσια ὕδατα τῆς ἀβύσσου.^45","leaf":"1026","pg":"1010","fn":["1026.0.44","1026.0.45"],"field":"3:15"}],"3:16":[{"s":0,"e":17,"h":"שָׁמַעְתִּי וַתִּרְגַּז בִּטְנִי לְקוֹל צָלְלוּ שְׂפָתַי יָבוֹא רָקָב בַּעֲצָמַי וְתַחְתַּי אֶרְגָּז אֲשֶׁר אָנוּחַ לְיוֹם צָרָה לַעֲלוֹת לְעַם יְגוּדֶנּוּ","l":"_Audivi, et contremuit venter meus; ad vocem tinnierunt labia mea; venit putredo in ossa mea, et subter me contremui; qui tacite exspectem diem calamitatis, donec veniat contra populum_ is qui _eum invadat._","t":"Ο΄. ἐφυλαξάμην, καὶ ἐπτοήθη ἡ κοιλία (alia exempl. καρδία^46) μου ἀπὸ φωνῆς προσευχῆς χειλέων μου, καὶ εἰσῆλθε τρόμος εἰς τὰ ὀστᾶ μου, καὶ ὑποκάτωθέν μου ἐταράχθη ἡ ἕξις (alia exempl. ἰσχύς^47) μου· ἀναπαύσομαι ἐν ἡμέρᾳ θλίψεως, τοῦ ἀναβῆναι εἰς λαὸν παροικίας μου. Ἄλλος· ἐταξάμην, καὶ ἀνεστατώθη τὰ σπλάγχνα μου ἀπὸ τῆς φωνῆς τοῦ στόματός σου· εἰσέδυ τρόμος εἰς τὰ ὀστᾶ μου, κατ’ ἐμαυτὸν ἐταράχθην· ταῦτα φυλάξεις ἐν ἡμέρᾳ θλίψεως, ἐπαγαγεῖν ἐπὶ ἔθνος πολεμοῦν τὸν λαόν σου.^48","leaf":"1026","pg":"1010","fn":["1026.0.46","1026.0.47","1026.0.48"],"field":"3:16"}],"3:17":[{"s":0,"e":19,"h":"כִּי־תְאֵנָה לֹא־תִפְרָח וְאֵין יְבוּל בַּגְּפָנִים כִּחֵשׁ מַעֲשֵׂה־זַיִת וּשְׁדֵמוֹת לֹא־עָשָׂה אֹכֶל גָּזַר מִמִּכְלָה צֹאן וְאֵין בָּקָר בָּרְפָתִים","l":"_Nam ficus non pullulabit, nec erit proventus in vitibus; mentietur_ (spem fallet) _opus oleae, et arva non ferent cibum; deficiet in caulis pecus, et non erit armentum in bovilibus._","t":"Ο΄. διότι συκῆ οὐ καρποφορήσει, καὶ οὐκ ἔσται γεννήματα ἐν ταῖς ἀμπέλοις· ψεύσεται ἔργον ἐλαίας, καὶ τὰ πεδία οὐ ποιήσει βρῶσιν· ἐξέλιπεν ἀπὸ βρώσεως πρόβατα, καὶ οὐχ ὑπάρχουσι βόες ἐπὶ φάτναις (alia exempl. add. ἐξιλάσεως αὐτῶν^49). Ἄλλος· ἡ συκῆ οὐ μὴ παραδῷ τὸν καρπὸν αὐτῆς, καὶ ἐν ταῖς ἀμπέλοις οὐκ ἔσται φορά· ἡ ἐλαία ἐξίτηλος ἔσται, ἡ δὲ γῆ οὐ μὴ ἐκθάλῃ βοτάνην· ἐκλείψει ἐκ μάνδρας πρόβατα, καὶ βόες οὐχ ὑπάρξουσιν ἐπὶ φάτναις.^50","leaf":"1027","pg":"1011","fn":["1027.0.49","1027.0.50"],"field":"3:17"}],"3:19":[{"s":0,"e":10,"h":"יֱהֹוִה אֲדֹנָי חֵילִי וַיָּשֶׂם רַגְלַי כָּאַיָּלוֹת וְעַל־בָּמוֹתַי יַדְרִכֵנִי לַמְנַצֵּחַ בִּנְגִינוֹתָי","l":"_Jova Dominus_ est _robur meum, et ponet pedes meos instar cervarum, et super arces meas incedere me faciet. Praecentori in Neginoth_ (instrumento pulsatili) _meo._","t":"Ο΄. κύριος ὁ θεὸς δύναμίς μου, καὶ τάξει τοὺς πόδας μου εἰς συντέλειαν (alia exempl. ὡς ἐλάφων, s. ὡσεὶ ἐλάφου^51)· ἐπὶ τὰ ὑψηλὰ ἐπιβιβᾷ με, τοῦ νικῆσαι ἐν τῇ ᾠδῇ αὐτοῦ. Ἄλλος· κύριος ὁ θεός μου ἔδωκέ μοι ἰσχὺν, καὶ κατέστησε τοὺς πόδας μου ἀσφαλεῖς, καὶ ἐπὶ τοὺς τραχήλους τῶν ἐχθρῶν μου ἐπιβιβᾷ με· ταχίσας κατεπαύσατο.^52","leaf":"1027","pg":"1011","fn":["1027.0.51","1027.0.52"],"field":"3:19"}]},"notes":{"1019.1.1":{"la":"Hieron.","en":"Hieron."},"1019.1.2":{"la":"Idem: “Ubi in Hebraico scriptum est RAU BAGGOIM, et nos transtulimus, _aspicite in gentibus,_ et LXX posuerunt, _videte contemptores,_ excepto Aq. et Sym. et Theod., qui cum nostra interpretatione concordant, in alia quadam editione ἀνωνύμῳ reperi, _videbitis calumniatores,_ et in alia similiter absque auctoris titulo, _videbitis declinantes._”","en":"The same: “Where in the Hebrew is written RAU BAGGOIM, and we rendered, _look among the nations,_ and the LXX put, _see, ye despisers,_ apart from Aq. and Sym. and Theod., who agree with our rendering, I found in a certain other anonymous (ἀνωνύμῳ) edition, _ye shall see the slanderers,_ and in another, likewise without the author's title, _ye shall see those turning aside._”"},"1019.1.3":{"la":"Cod. 86 affert: καὶ ἴδετε, cum ⅄ super ἴδετε. Cf. Hex. ad Mich. i. 15. Sic Codd. 36, 62, alii.","en":"Cod. 86 cites: καὶ ἴδετε, with ⅄ over ἴδετε. Cf. Hex. on Mich. i. 15. Thus Codd. 36, 62, and others."},"1019.1.4":{"la":"Sic Syro-hex. cum notula: “÷ Hic obelus non positus erat in Hexaplis.”","en":"Thus Syro-hex. with a little note: “÷ This obelus was not placed in the Hexapla.”"},"1019.1.5":{"la":"Hieron.: “Sym. pro eo quod diximus, _quia opus factum est in diebus vestris,_ interpretatus est, _quia opus fiet in diebus vestris;_ cetera similiter.”","en":"Hieron.: “Sym., for what we said, _for a work is done in your days,_ rendered, _for a work shall be done in your days;_ the rest similarly.”"},"1019.1.6":{"la":"Theodoret. Pro δόγματι ἑαυτοῦ, quod in Schulzii Cod. C, et Parsonsii Codd. 42, 240 legitur, in editis est δόγμα τὸ ἑαυτοῦ, quae minus proba est syntaxis. Hieron. Latine vertit: _ipsa_ (gens) _sibi judicabit, et decreto suo egredietur,_ male pro, _et decretum suum vindicabit,_ s. _exsequetur._ Syro-hex. tantum affert: ܣ. ܗܘ ܠܗ ܢܕܘܢ ܀","en":"Theodoret. For δόγματι ἑαυτοῦ, which is read in Schulz's Cod. C, and Parsons' Codd. 42, 240, the editions have δόγμα τὸ ἑαυτοῦ, which is less sound syntax. Hieron. renders in Latin: _it_ (the nation) _shall judge for itself, and shall go forth by its own decree,_ wrongly for, _and shall vindicate its own decree,_ or _shall carry it out._ Syro-hex. only cites: ܣ. ܗܘ ܠܗ ܢܕܘܢ ܀"},"1019.1.7":{"la":"Cod. 86.","en":"Cod. 86."},"1019.1.8":{"la":"Hieron.: “In eo quod . . . LXX transtulerunt: _Et equitabuntur equites ejus_ . . . interpretatus est Sym.: _effundentur_ [quasi a פָּשָׂה, _diffudit se._ Cf. Hex. ad Levit. xiii. 5] _equites ejus,_ id est, corruent et allidentur in terram.”","en":"Hieron.: “In that which . . . the LXX rendered: _And his horsemen shall ride_ . . . Sym. rendered: _his horsemen shall be poured out_ [as if from פָּשָׂה, _it spread itself._ Cf. Hex. on Levit. xiii. 5], that is, they shall rush down and be dashed to the ground.”"},"1019.1.9":{"la":"Theodoret. Hieron. Hebraea vertit: _Facies eorum ventus urens,_ suppressa voce difficili מְגַמַּת.","en":"Theodoret. Hieron. renders the Hebrew: _Their faces are a burning wind,_ suppressing the difficult word מְגַמַּת."},"1019.1.10":{"la":"Syro-hex. ܐ. ܢܫܬܒܚ[?] ܀ ܣ. ܢܒܙܚ ܀ Aquilae versionem Chaldaico-Syriacum קַלֵּס, _laudavit, celebravit,_ respicere quivis videt. Ad Sym. cf. Ezech. xxii. 5 in LXX et Syro-hex.","en":"Syro-hex. ܐ. ܢܫܬܒܚ[?] ܀ ܣ. ܢܒܙܚ ܀ Anyone can see that Aquila's version has regard to the Chaldaeo-Syriac קַלֵּס, _he praised, celebrated._ On Sym. cf. Ezech. xxii. 5 in the LXX and Syro-hex."},"1020.0.11":{"la":"Syro-hex. ܣ. ܓܘܚܟܐ (ΓЄΛΟϹ) ܕܝܠܗ ܀ ܐ. ܓܘܚ̈ܟܐ (ΓЄΛΑϹΜΑΤΑ) ܀","en":"Syro-hex. ܣ. ܓܘܚܟܐ (ΓЄΛΟϹ) ܕܝܠܗ ܀ ܐ. ܓܘܚ̈ܟܐ (ΓЄΛΑϹΜΑΤΑ) ܀"},"1020.0.12":{"la":"Hieron.: “Et postea _corruet;_ pro quo Aq. et Sym. transtulerunt, καὶ πλημμελήσει, id est, _et delinquet;_ hanc habente Scriptura sancta consuetudinem, ut VASAM, id est, _delinquet,_ ponat pro eo quod est, _desinet esse quod fuerat._”","en":"Hieron.: “And afterwards _shall fall;_ for which Aq. and Sym. rendered, καὶ πλημμελήσει, that is, _and shall transgress;_ Holy Scripture having this custom, that it puts VASAM, that is, _shall transgress,_ for that which is, _shall cease to be what it had been._”"},"1020.0.13":{"la":"Idem: “Sym. manifestius: _Nonne tu a principio, Domine Deus meus, Sancte meus, ut non moreremur?_”","en":"The same: “Sym. more plainly: _Art thou not from the beginning, O Lord my God, my Holy One, that we should not die?_”"},"1020.0.14":{"la":"Cod. 86.","en":"Cod. 86."},"1020.0.15":{"la":"Idem affert: Σ. κύριε εἰς τὸ κρίνειν. Σ. κραταιὸν—ἔστησαν (sic) αὐτόν. Hieron. autem Symmacho continuat: _Domine, ad judicandum posuisti eum, fortem ad corripiendum constituisti illum._","en":"The same cites: Σ. κύριε εἰς τὸ κρίνειν. Σ. κραταιὸν—ἔστησαν (sic) αὐτόν. But Hieron. continues for Symmachus: _O Lord, thou hast set him for judgment, thou hast established him strong for correction._"},"1020.0.16":{"la":"Sic Codd. III, XII, 22, 26, 36, alii, Hieron., Syro-hex.","en":"Thus Codd. III, XII, 22, 26, 36, and others, Hieron., Syro-hex."},"1020.0.17":{"la":"Cod. 86. Lectionem, apud Waltonum anonymam (cum ὡς pro ὥστε, et εἰς pro πρὸς), prorsus neglexit Montef.","en":"Cod. 86. The reading, anonymous in Walton (with ὡς for ὥστε, and εἰς for πρὸς), Montef. completely neglected."},"1020.0.18":{"la":"Sic Codd. 36, 49, 62 (cum αὐτὸ), alii. Hieron.: _justiorem se._","en":"Thus Codd. 36, 49, 62 (with αὐτὸ), and others. Hieron.: _more righteous than himself._"},"1020.0.19":{"la":"Theodoret., et MS. Reg. apud Montef.","en":"Theodoret., and MS. Reg. in Montef."},"1020.0.20":{"la":"Verba inclusa desunt in Comp., Codd. 23, 91, Hieron., Syro-hex.","en":"The bracketed words are absent from Comp., Codd. 23, 91, Hieron., Syro-hex."},"1020.0.21":{"la":"Sic Cod. 86 (cum ἐκκαινώσει) in marg. sine nom.","en":"Thus Cod. 86 (with ἐκκαινώσει) in the margin without name."},"1020.1.1":{"la":"Hieron.: “Pro _munitione_ et _petra,_ in cujus locum Sym. interpretatus est _conclusum,_ in Hebraeo ponitur MASUR, quod Theod. _gyrum,_ Aq. et Quinta ed. _circinum_ transtulerunt.”","en":"Hieron.: “For _fortification_ and _rock,_ in place of which Sym. rendered _enclosed,_ in the Hebrew is put MASUR, which Theod. rendered _circuit,_ Aq. and the Fifth ed. _compass._”"},"1020.1.2":{"la":"Idem: “Sym. manifestius est persecutus: _Quasi custos super speculam_ (_meam_) _stabo, et stabo_ cet.” Syro-hex. affert: ܣ. ܐܝܟ ܢܛܘܪܐ ܥܠ ܕܣܘܟܬܐ[?] ܕܝܠܝ ܐܩܘܡ ܀ Pro ܕܣܘܟܬܐ[?], quae codicis est lectio, legendum esse ܕܣܘܩܬܐ[?], monitum in _Otio Norvic._ p. 73.","en":"The same: “Sym. has followed it out more plainly: _As a watchman upon_ (_my_) _watch-tower I will stand, and I will stand_ etc.” Syro-hex. cites: ܣ. ܐܝܟ ܢܛܘܪܐ ܥܠ ܕܣܘܟܬܐ[?] ܕܝܠܝ ܐܩܘܡ ܀ That for ܕܣܘܟܬܐ[?], which is the reading of the codex, ܕܣܘܩܬܐ[?] should be read, is pointed out in _Otium Norvic._ p. 73."},"1020.1.3":{"la":"Hieron.","en":"Hieron."},"1020.1.4":{"la":"Idem: “Pro _tabulis_ et _buxo,_ quod Hebraice dicitur ALLUOTH, Sym. interpretatus est _paginas._”","en":"The same: “For _tablets_ and _box-wood,_ which in Hebrew is called ALLUOTH, Sym. rendered _pages._”"},"1021.0.5":{"la":"Cod. 86.","en":"Cod. 86."},"1021.0.6":{"la":"Idem. Aquilae lectionem memorat Euseb. in Dem. Evang. p. 277.","en":"The same. Aquila's reading is mentioned by Euseb. in Dem. Evang. p. 277."},"1021.0.7":{"la":"Euseb. ibid. p. 276. Idem p. 278 ἐλεύσεται pro ἥξει allegat, omisso δέ.","en":"Euseb. ibid. p. 276. The same on p. 278 cites ἐλεύσεται for ἥξει, omitting δέ."},"1021.0.8":{"la":"Cod. 86 (cum scriptura στραγεύσεται, s. στραγεύσηται). Cf. Hex. ad Jud. xix. 8. Prov. xxiv. 10.","en":"Cod. 86 (with the spelling στραγεύσεται, or στραγεύσηται). Cf. Hex. on Jud. xix. 8. Prov. xxiv. 10."},"1021.0.9":{"la":"Euseb. ibid. p. 278. Cod. 86 affert: Ἀ. ἰδοὺ νωχελευομένου. Cf. Hex. ad Prov. xviii. 9. xxiv. 10.","en":"Euseb. ibid. p. 278. Cod. 86 cites: Ἀ. ἰδοὺ νωχελευομένου. Cf. Hex. on Prov. xviii. 9. xxiv. 10."},"1021.0.10":{"la":"Hieron.: “Et ubi LXX posuerunt: _Justus autem ex fide mea vivet,_ omnes aequaliter transtulerunt, _ex fide sua vivet._” Syro-hex. ܗܘ ܕܝܢ ܟܐܢܐ ܡܢ ܗܝܡܢܘܬܐ ܕܝܠܗ ܢܚܐ ܀","en":"Hieron.: “And where the LXX put: _But the just shall live by my faith,_ all alike rendered, _shall live by his faith._” Syro-hex. ܗܘ ܕܝܢ ܟܐܢܐ ܡܢ ܗܝܡܢܘܬܐ ܕܝܠܗ ܢܚܐ ܀"},"1021.0.11":{"la":"Euseb. in continuatione.","en":"Euseb. in the continuation."},"1021.0.12":{"la":"Hieron.: “Denique Sym. significantius interpretans ait: _Justus autem per fidem propriam suam vivet,_ quod Graece dicitur: ὁ (δὲ) δίκαιος κ. τ. ἑ.”","en":"Hieron.: “Accordingly Sym., rendering more expressively, says: _But the just shall live by his own proper faith,_ which in Greek is said: ὁ (δὲ) δίκαιος κ. τ. ἑ.”"},"1021.0.13":{"la":"Cod. 86.","en":"Cod. 86."},"1021.0.14":{"la":"Hieron.: “Sic vir superbus _non decorabitur,_ nec voluntatem suam _perducet ad finem,_ et juxta Sym. οὐκ εὐπορήσει, hoc est, _in rerum omnium erit penuria._” (Hieronymi versio, _non decorabitur_ (οὐχ ὡραιωθήσεται) Aquilam auctorem referre videtur. Cf. Hex. ad Psal. xxxii. 1. Jesai. lii. 7.)","en":"Hieron.: “So the proud man _shall not be adorned,_ nor shall he _bring_ his will _to an end,_ and according to Sym. οὐκ εὐπορήσει, that is, _he shall be in want of all things._” (Jerome's version, _shall not be adorned_ (οὐχ ὡραιωθήσεται), seems to point to Aquila as its author. Cf. Hex. on Psal. xxxii. 1. Jesai. lii. 7.)"},"1021.0.15":{"la":"Syro-hex. ܣ. ܕܠܡܐ ܠܐ ܗܘܐ ܗܠܝܢ ܟܠܗܝܢ ܥܠܘܗܝ ܠܡܬܠܐ ܢܬܢܣܒܢ: ܘܡܐܡܪܐ ܕܐܘܚܕܬܐ ܥܠܘܗܝ ܀[?]","en":"Syro-hex. ܣ. ܕܠܡܐ ܠܐ ܗܘܐ ܗܠܝܢ ܟܠܗܝܢ ܥܠܘܗܝ ܠܡܬܠܐ ܢܬܢܣܒܢ: ܘܡܐܡܪܐ ܕܐܘܚܕܬܐ ܥܠܘܗܝ ܀[?]"},"1021.0.16":{"la":"Idem: ܬ. ܢܬܬܥܝܪܘܢ ܀","en":"The same: ܬ. ܢܬܬܥܝܪܘܢ ܀"},"1021.0.17":{"la":"Cod. 86.","en":"Cod. 86."},"1021.0.18":{"la":"Syro-hex. Copula legitur in libris omnibus.","en":"Syro-hex. The copula is read in all the books."},"1021.0.19":{"la":"Cod. 86.","en":"Cod. 86."},"1021.0.20":{"la":"Hieron.: “Sed et Aq. aliud quiddam quam nos diximus posuit, καὶ μάζα, id est, _et massa de ligno respondebit._” Cod. 86 affert: Ἀ. μάζα.","en":"Hieron.: “But Aq. too put something other than we said, καὶ μάζα, that is, _and the mass from the wood shall answer._” Cod. 86 cites: Ἀ. μάζα."},"1021.0.21":{"la":"Hieron.: “Porro quod nos interpretati sumus: _Et lignum quod inter juncturas aedificiorum est, respondebit;_ pro quo LXX posuerunt: _Et scarabaeus de ligno loquetur ea,_ manifestius more suo transtulit Sym.: καὶ σύνδεσμος κ. τ. ἑ., id est, _et junctura aedificii lignea loquetur ea._” Cod. 86 affert: Σ. σύνδεσμος ξύλινος. Theodoret.: ἀντὶ δὲ τοῦ κάνθαρος, σύνδεσμος ξύλινος ὁ Σύμ. τέθεικεν.","en":"Hieron.: “Moreover what we rendered: _And the timber which is between the joints of the buildings shall answer;_ for which the LXX put: _And the beetle out of the wood shall speak them,_ Sym., after his manner, rendered more plainly: καὶ σύνδεσμος κ. τ. ἑ., that is, _and the wooden joint of the building shall speak them._” Cod. 86 cites: Σ. σύνδεσμος ξύλινος. Theodoret.: ἀντὶ δὲ τοῦ κάνθαρος, σύνδεσμος ξύλινος ὁ Σύμ. τέθεικεν."},"1021.0.22":{"la":"Hieron.: “Theod. quoque, καὶ σύνδεσμος [fort. ἔνδεσμος] κ. τ. ἑ.; necnon et Quinta ed., καὶ σύνδεσμος κ. τ. ἑ.: quae et ipsae interpretationes cum Symmachi et nostra interpretatione concordant. Quod enim lingua Hebraica dicitur CHAPHIS, lignum significat, quod ad continendos parietes in medio structurae ponitur, et vulgo apud Graecos appellatur ἱμάντωσις.” Cod. 86 affert: Θ. ἔνδεσμος. S. Cyril. in XII Proph. p. 540 B: Ἰστέον δὲ, ὅτι ἀντὶ τοῦ, κάνθαρος, εἰπεῖν, ἕτεροι τῶν ἑρμηνευτῶν ἐκδεδώκασιν, 6 N 2 ἔνδεσμος ξύλου· ὅθεν ἐστὶν ἐννοεῖν, ὅτι τάχα που τὰς τῶν οἰκιῶν μίτρας, καὶ τὴν ἐν αὐταῖς ἀναπλοκὴν τῶν ξύλων, ἤτοι σύνδεσμον, κανθάρους ὠνόμαζον κατ᾽ ἐκεῖνο καιροῦ, διὰ τὸ οἷον πολλοῖς ἀντέχειν ποσὶ τὴν ἐπικειμένην αὐτοῖς ὀροφήν.","en":"Hieron.: “Theod. also, καὶ σύνδεσμος [perhaps ἔνδεσμος] κ. τ. ἑ.; and likewise the Fifth ed., καὶ σύνδεσμος κ. τ. ἑ.: which renderings themselves also agree with that of Symmachus and with ours. For what in the Hebrew tongue is called CHAPHIS signifies the timber which is placed in the middle of the structure to hold the walls together, and is commonly called by the Greeks ἱμάντωσις.” Cod. 86 cites: Θ. ἔνδεσμος. S. Cyril. in XII Proph. p. 540 B: Ἰστέον δὲ, ὅτι ἀντὶ τοῦ, κάνθαρος, εἰπεῖν, ἕτεροι τῶν ἑρμηνευτῶν ἐκδεδώκασιν,"},"1022.0.23":{"la":"Hieron.: “Reperi, exceptis quinque editionibus, id est, Aquilae, Symmachi, LXX, Theodotionis, et Quinta, in duodecim prophetis et duas alias editiones, in quarum una scriptum est: _Quia lapis_ cet.; et in altera: _Lapis enim_ cet.”","en":"Hieron.: “I found, besides the five editions, that is, of Aquila, Symmachus, the LXX, Theodotion, and the Fifth, in the twelve prophets two other editions as well, in one of which is written: _For the stone_ etc.; and in the other: _For a stone_ etc.”"},"1022.0.24":{"la":"Sic Comp., Codd. 22, 36, 42, 51 (cum -ψει), 62 (cum καλύψαι), alii, Hieron., Syro-hex. (ܠܡܚܦܝܘ[?] ܝܡ̈ܡܐ).","en":"Thus Comp., Codd. 22, 36, 42, 51 (with -ψει), 62 (with καλύψαι), and others, Hieron., Syro-hex. (ܠܡܚܦܝܘ[?] ܝܡ̈ܡܐ)."},"1022.0.25":{"la":"Hieron.: “Aquila, ἐξ ἐπιτρίψεως [Vallars.: ‘Ad fidem Regii MS. restituimus ἐπιτρίψεως, qua in lectione et Barberinus alter a Montef. laudatus consentit. Antea erat ἐκπέμψεως’] χόλου σου, quod possumus vertere, _de emissione furoris tui._” Cod. 86 affert: Ἀ. ἐξ ἐπιρίψεως (non, ut Montef., ἐπιτρίψεως) χόλους (sic); quae lectio ab Hieronymi _emissione_ propius abesse videtur.","en":"Hieron.: “Aquila, ἐξ ἐπιτρίψεως [Vallars.: ‘On the authority of the Regius MS. we have restored ἐπιτρίψεως, in which reading the other Barberini MS. cited by Montef. also agrees. Formerly it was ἐκπέμψεως’] χόλου σου, which we can render, _from the sending forth of thy fury._” Cod. 86 cites: Ἀ. ἐξ ἐπιρίψεως (not, as Montef., ἐπιτρίψεως) χόλους (sic); which reading seems to stand nearer to Jerome's _sending forth._"},"1022.0.26":{"la":"Idem: “Pro _subversione turbida_ Sym. interpretatus est: καὶ ἀφιῶν κ. τ. ἑ., id est, _et emittens absque judicio furorem suum._” Etiam Cod. 86: Σ. ἀφιῶν κ. τ. ἑ.","en":"The same: “For _turbulent overthrow_ Sym. rendered: καὶ ἀφιῶν κ. τ. ἑ., that is, _and sending forth his fury without judgment._” Also Cod. 86: Σ. ἀφιῶν κ. τ. ἑ."},"1022.0.27":{"la":"Idem: “Theod. ἀπὸ χύσεώς σου, quod interpretatur, _ab effusione tua._”","en":"The same: “Theod. ἀπὸ χύσεώς σου, which means, _from thy pouring out._”"},"1022.0.28":{"la":"Idem: “Quinta ed. ἐξ ἀπροσδοκήτου κ. τ. ἑ., quod significat, _de subversione insperata irae tuae._”","en":"The same: “The Fifth ed. ἐξ ἀπροσδοκήτου κ. τ. ἑ., which signifies, _from the unexpected overthrow of thy wrath._”"},"1022.0.29":{"la":"Idem: “In alia editione reperi: οὐαὶ τῷ ποτίζοντι κ. τ. ἑ., quod ipsum in lingua nostra sonat: _Vae qui potum dat amico suo turbinem volantem._”","en":"The same: “In another edition I found: οὐαὶ τῷ ποτίζοντι κ. τ. ἑ., which in our tongue means: _Woe to him who gives his friend a flying whirlwind to drink._”"},"1022.0.30":{"la":"Idem: “Sed et alibi translatum legi: _Vae qui potum dat proximo suo_ ἔκστασιν ὀχλουμένην, id est, _amentiam turbidam._”","en":"The same: “But elsewhere too I have read it rendered: _Woe to him who gives his neighbour to drink_ ἔκστασιν ὀχλουμένην, that is, _turbulent madness._”"},"1022.0.31":{"la":"Cod. 86. Parsons. e Cod. 42 exscripsit: Σ. αἰσχύνην. S. Cyril. in XII Proph. p. 544 A: Ἐκδεδώκασι γὰρ οἱ ἕτεροι τῶν ἑρμηνευτῶν ἀντὶ τῶν σπηλαίων, τὴν γύμνωσιν.","en":"Cod. 86. Parsons transcribed from Cod. 42: Σ. αἰσχύνην. S. Cyril. in XII Proph. p. 544 A: Ἐκδεδώκασι γὰρ οἱ ἕτεροι τῶν ἑρμηνευτῶν ἀντὶ τῶν σπηλαίων, τὴν γύμνωσιν."},"1022.0.32":{"la":"Sic Comp., Ald., Codd. 22, 23, 51, alii, invito Syro-hex., qui legit: πίε καὶ σύ· καὶ σὺ καρδία κ. τ. ἑ. Hieron.: _et commovere_ (om. καὶ σείσθητι).","en":"Thus Comp., Ald., Codd. 22, 23, 51, and others, against Syro-hex., which reads: πίε καὶ σύ· καὶ σὺ καρδία κ. τ. ἑ. Hieron.: _and be moved_ (omitting καὶ σείσθητι)."},"1022.0.33":{"la":"Cod. 86. Hieron. Hebraeum vertit: _et consopire._ Uterque pro הֵעָרֵל interpretatus est הֵרָעֵל, _vertigine corripere._ Cf. Hex. ad Psal. lix. 5. Jesai. li. 17.","en":"Cod. 86. Hieron. renders the Hebrew: _and fall asleep._ Both interpreted הֵעָרֵל as הֵרָעֵל, _to be seized with dizziness._ Cf. Hex. on Psal. lix. 5. Jesai. li. 17."},"1022.0.34":{"la":"Cod. 86. Aquilae αἷμα aut ad Hebraeum מִדְּמֵי, Ο΄. δι᾽ αἵματα, pertinet; aut pro ἀδικία male exaratum.","en":"Cod. 86. Aquila's αἷμα either belongs to the Hebrew מִדְּמֵי, Ο΄. δι᾽ αἵματα; or is miswritten for ἀδικία."},"1022.0.35":{"la":"Cod. 86. Nescio quo errore Syrus noster ad θηρίων affert: Ἀ. ἀνθρώπων (ܕܒܢܝ̈ܢܫܐ).","en":"Cod. 86. By what error I know not, our Syriac cites on θηρίων: Ἀ. ἀνθρώπων (ܕܒܢܝ̈ܢܫܐ)."},"1022.0.36":{"la":"Cod. 86.","en":"Cod. 86."},"1022.0.37":{"la":"Sic Comp., Ald., Codd. 22, 26, 36, alii, Hieron., Syro-hex.","en":"Thus Comp., Ald., Codd. 22, 26, 36, and others, Hieron., Syro-hex."},"1022.0.38":{"la":"Syro-hex. ܬ. ܟܕ ܓܒܠ[?] ܀","en":"Syro-hex. ܬ. ܟܕ ܓܒܠ[?] ܀"},"1022.0.39":{"la":"Hieron.: “Et facit simulacra _muta,_ vel _surda:_ κωφὰ quippe apud Graecos utrumque significat; quanquam Sym. ἄλαλα interpretans, _muta_ magis videatur intellexisse quam _surda._”","en":"Hieron.: “And he makes images _dumb,_ or _deaf:_ for κωφὰ among the Greeks signifies both; although Sym., rendering ἄλαλα, seems to have understood _dumb_ rather than _deaf._”"},"1022.0.40":{"la":"Idem: “Unde et Aq. significantius vertit Hebraicum, dicens: _Et spiritus ejus non est in visceribus,_ sive _in medio ejus._”","en":"The same: “Whence Aq. also renders the Hebrew more expressively, saying: _And his spirit is not in the bowels,_ or _in the midst of it._”"},"1023.1.1":{"la":"Hieron.: “Aq. et Sym. et Quinta ed., sicut nos, _pro ignorationibus_ transtulerunt; solus Theod. ὑπὲρ τῶν ἑκουσιασμῶν, id est, _pro voluntariis,_ et _pro his qui sponte delinquunt._ Hoc propterea ut intelligamus, exceptis LXX, nullum _orationem cum cantico_ transtulisse. Nam et in Hebraico habet AL SEGIONOTH, quod dicitur ἐπὶ ἀγνοημάτων, et nos transtulimus, _pro ignorationibus._”","en":"Hieron.: “Aq. and Sym. and the Fifth ed., like us, rendered _for ignorances;_ Theod. alone ὑπὲρ τῶν ἑκουσιασμῶν, that is, _for voluntary sins,_ and _for those who transgress of their own accord._ This [I say] in order that we may understand that, apart from the LXX, no one rendered _a prayer with a song._ For in the Hebrew too it has AL SEGIONOTH, which is said ἐπὶ ἀγνοημάτων, and we rendered, _for ignorances._”"},"1023.1.2":{"la":"Sic in textu Codd. 62, 86, 147, qui per totum hoc canticum inter se amice conspirant. “In Cod. Barberino affertur interpretatio alia Cantici Habacuc cum hac nota in fine: Τὴν ᾠδὴν τοῦ Ἀμβακοὺμ οὐχ εὗρον συμφωνοῦσαν οὔτε τοῖς Ο΄, οὔτε Ἀκύλᾳ, οὔτε Συμμάχῳ, οὔτε Θεοδοτίωνι. Ζητήσεις οὖν εἰ τῆς Ε΄ ἢ τῆς S΄ ἐκδόσεώς ἐστι. Immo nec cum Quinta, nec cum Sexta convenit, ut ex earum locis supra allatis liquidum est: quare ut incerti interpretis postrema semper ponitur, praemissa voce Ἄλλος, per totum canticum. Esse vero Septimam editionem vix est quod dubitemus.”—_Montef._","en":"Thus in the text Codd. 62, 86, 147, which throughout this whole song agree amicably with one another. “In the Barberini Cod. another version of the Song of Habakkuk is adduced, with this note at the end: Τὴν ᾠδὴν τοῦ Ἀμβακοὺμ οὐχ εὗρον συμφωνοῦσαν οὔτε τοῖς Ο΄, οὔτε Ἀκύλᾳ, οὔτε Συμμάχῳ, οὔτε Θεοδοτίωνι. Ζητήσεις οὖν εἰ τῆς Ε΄ ἢ τῆς S΄ ἐκδόσεώς ἐστι. Nay, it agrees neither with the Fifth nor with the Sixth, as is clear from their passages adduced above: wherefore, as that of an uncertain translator, it is always placed last, with the word Ἄλλος prefixed, throughout the whole song. That it is the Seventh edition there is scarcely reason for us to doubt.”—_Montef._"},"1023.1.3":{"la":"Sic Comp., Ald., Codd. 22, 36, 42, alii, Hieron., Syro-hex.","en":"Thus Comp., Ald., Codd. 22, 36, 42, and others, Hieron., Syro-hex."},"1023.1.4":{"la":"Hieron.: “Quod autem LXX dixerunt, _consideravi et obstupui,_ nec in Hebraeo habetur, nec apud quempiam aliorum interpretum, ut sublatis his quae in Hebraico non habentur, possit legi juxta LXX: _Domine, opera tua in medio duorum animalium cognosceris:_ quod quia ἀδιανόητον videbatur, superiora conjuncta sunt.”","en":"Hieron.: “But what the LXX said, _I considered and was amazed,_ is found neither in the Hebrew nor in any of the other translators, so that, when what is not found in the Hebrew has been removed, it can be read according to the LXX: _O Lord, thy works; in the midst of two living creatures thou shalt be known:_ and because this seemed ἀδιανόητον, the preceding words were joined to it.”"},"1023.1.5":{"la":"Euseb. in Dem. Evang. p. 279 (qui in textu LXXvirali ζωῶν pingere jubet, invitis Hieron. et Syro-hex.). Syro-hex. affert: Ἀ. Θ. ζώωσον αὐτόν (ܐܚܝܝܗܝ). Σ. ἀναζώωσον αὐτόν (ܐܚܝܝܗܝ ܡܢ ܕܪܝܫ[?]). Hieron.: “Pro eo quod nos et Aq. et Theod. transtulimus, _vivifica illud,_ Sym. interpretatus est, _revivifica illud._”","en":"Euseb. in Dem. Evang. p. 279 (who directs ζωῶν to be written in the text of the LXX, against Hieron. and Syro-hex.). Syro-hex. cites: Ἀ. Θ. ζώωσον αὐτόν (ܐܚܝܝܗܝ). Σ. ἀναζώωσον αὐτόν (ܐܚܝܝܗܝ ܡܢ ܕܪܝܫ[?]). Hieron.: “For what we and Aq. and Theod. rendered, _quicken it,_ Sym. rendered, _quicken it again._”"},"1023.1.6":{"la":"Obelus est in Syro-hex. Hieron.: “Sequitur: _Cum advenerit tempus, demonstraberis; cum turbata fuerit anima mea;_ quod, exceptis LXX, nec in Hebraico, nec apud quemquam aliorum habetur interpretum . . . Quod autem infertur, _cum turbata fuerit anima mea,_ apud LXX interpretum editionem cum posterioribus copulatur, ut possit legi: _Cum turbata fuerit anima mea in ira,_ et hucusque distinctio: deinceps inferatur, _misericordiae recordaberis._”","en":"The obelus is in Syro-hex. Hieron.: “There follows: _When the time shall come, thou shalt be shown; when my soul shall be troubled;_ which, apart from the LXX, is found neither in the Hebrew nor in any of the other translators . . . But what is added, _when my soul shall be troubled,_ is joined in the edition of the LXX translators with what follows, so that it can be read: _When my soul shall be troubled in wrath,_ and the division [falls] here: then let there follow, _thou wilt remember mercy._”"},"1023.1.7":{"la":"Sic Codd. 62, 86 (cum λοιβὸς), 147.","en":"Thus Codd. 62, 86 (with λοιβὸς), 147."},"1023.1.8":{"la":"Syro-hex. ܐ. ܣ. ܬ. ܕܦܐܪܢ ܀ In textu Φαρὰν reprobant Ald., Codd. 22, 23, 26, alii, Hieron., Syro-hex. Codd. 62, 86, 147 Φαρὰν habent, non κατασκίου δασέος.","en":"Syro-hex. ܐ. ܣ. ܬ. ܕܦܐܪܢ ܀ In the text Φαρὰν is rejected by Ald., Codd. 22, 23, 26, and others, Hieron., Syro-hex. Codd. 62, 86, 147 have Φαρὰν, not κατασκίου δασέος."},"1023.1.9":{"la":"Hieron.: “Aq. et Sym. et Quinta ed. ipsum Hebraicum posuerunt THEMAN; solus Theod. quid significaret THEMAN, interpretatus est, dicens: _Eloim ab austro veniet, et Sanctus de monte Pharan, in finem._ Ex quo intelligimus, a solis LXX positum, _de monte umbroso et condenso._” Ad Ἐλωεὶμ cf. Hex. ad Mich. iii. 7. vi. 8. Paulo aliter Euseb. ibid. p. 280: Μεταλαμβάνεται γὰρ Θαιμὰν εἰς τὸν νότον· διόπερ ὁ Θεοδοτίων τοῦτον ἑρμηνεύει τὸν τρόπον, ὁ θεὸς ἀπὸ νοτίου ἥξει. Theodoret.: τὸ Θαιμὰν οἱ μὲν λίβα, οἱ δὲ νότον ἡρμηνεύκασιν. Cf. Hex. ad Amos i. 12.","en":"Hieron.: “Aq. and Sym. and the Fifth ed. put the Hebrew itself, THEMAN; Theod. alone interpreted what THEMAN signifies, saying: _Eloim shall come from the south, and the Holy One from mount Pharan, to the end._ From which we understand that it was put by the LXX alone, _from the shady and thick mountain._” On Ἐλωεὶμ cf. Hex. on Mich. iii. 7. vi. 8. Somewhat differently Euseb. ibid. p. 280: Μεταλαμβάνεται γὰρ Θαιμὰν εἰς τὸν νότον· διόπερ ὁ Θεοδοτίων τοῦτον ἑρμηνεύει τὸν τρόπον, ὁ θεὸς ἀπὸ νοτίου ἥξει. Theodoret.: τὸ Θαιμὰν οἱ μὲν λίβα, οἱ δὲ νότον ἡρμηνεύκασιν. Cf. Hex. on Amos i. 12."},"1023.1.10":{"la":"Hieron.: “Sed et hoc quod LXX transtulerunt διάψαλμα, et nos posuimus _semper,_ Sym. interpretatus est _in aeternum;_ Theod. _in finem;_ Quinta ed. ipsum Hebraicum SELA.” Aliter tamen iidem interpp. in Hex. ad Psal. iii. 3. lxxiv. 4. lxxv. 4, 10.","en":"Hieron.: “But this too, which the LXX rendered διάψαλμα, and we put _always,_ Sym. rendered _for ever;_ Theod. _to the end;_ the Fifth ed. the Hebrew itself, SELA.” Otherwise, however, the same translators in Hex. on Psal. iii. 3. lxxiv. 4. lxxv. 4, 10."},"1023.1.11":{"la":"Sic in textu Codd. 62, 86, 147. Vox διάψαλμα deest in Ald., Codd. III, 23, 26, 36, aliis, invito Syro-hex.","en":"Thus in the text Codd. 62, 86, 147. The word διάψαλμα is absent from Ald., Codd. III, 23, 26, 36, and others, against Syro-hex."},"1023.1.12":{"la":"“Ex Colbert. στιχηρῶς scripto, qui continet Psalmos et Cantica Scripturae. Coislin. vero habet: Ἀ. Θ. ἀπεκάλυψεν ὁ οὐρανὸς κ. τ. ἑ.”—_Montef._ Praeterea corrigendum videtur ἐπεκάλυψεν, necnon, ut in lectione sequenti, τὴν εὐπρ. τῆς δ. αὐτοῦ; ut tamen ne sic quidem lectio Aquilam auctorem habeat.","en":"“From the Colbert MS. written στιχηρῶς, which contains the Psalms and the Canticles of Scripture. But the Coislin has: Ἀ. Θ. ἀπεκάλυψεν ὁ"},"1024.0.13":{"la":"Sic in textu Codd. 62, 86, 147. Ad ἐκάλυψεν οὐρανοὺς Nobil. notat: “In uno vetustissimo libro, majoribus literis exarato, principium hujus orationis convenit cum aliis libris; ab hoc vero loco, cetera ita posita sunt: ἐκάλυψεν οὐρανοὺς ἡ εὐπρέπεια τῆς δόξης αὐτοῦ, κ. τ. ἑ.” Iste liber est Parsonsii Cod. 23.","en":"Thus in the text Codd. 62, 86, 147. On ἐκάλυψεν οὐρανοὺς Nobil. notes: “In one very ancient book, written in larger letters, the beginning of this prayer agrees with the other books; but from this place on, the rest is set down thus: ἐκάλυψεν οὐρανοὺς ἡ εὐπρέπεια τῆς δόξης αὐτοῦ, κ. τ. ἑ.” That book is Parsons' Cod. 23."},"1024.0.14":{"la":"Iidem. “Hanc lectionem τοῖς Ο΄ tribuit Coislin. in margine positam.”—_Montef._","en":"The same. “This reading, placed in the margin, the Coislin ascribes τοῖς Ο΄.”—_Montef._"},"1024.0.15":{"la":"Hieron.: “Pro eo quod LXX interpretati sunt, _et posuit dilectionem robustam fortitudinis suae,_ et nos diximus, _ibi abscondita est fortitudo ejus,_ Aq. transtulit, _et posuit absconsionem fortitudinis suae;_ Sym., _et posuit absconditam fortitudinem suam;_ solus Theod. nostrae translationi congruens ait, _et ibi absconsio fortitudinis ejus._”","en":"Hieron.: “For what the LXX rendered, _and he set the strong love of his might,_ and we said, _there is his might hidden,_ Aq. rendered, _and he set the hiding of his might;_ Sym., _and he set his might hidden;_ Theod. alone, agreeing with our translation, says, _and there is the hiding of his might._”"},"1024.0.16":{"la":"Sic in textu Codd. 23 (cum ἀπεστ.), 62, 86, 147.","en":"Thus in the text Codd. 23 (with ἀπεστ.), 62, 86, 147."},"1024.0.17":{"la":"Hieron.: “Denique et Aq. ita interpretatus est, _ante faciem ejus ibit pestis;_ Sym., _ante faciem ejus praecedet mors;_ Quinta ed., _ante faciem ejus ambulabit mors;_ soli LXX et Theod. _sermonem_ pro _morte_ interpretati sunt.”","en":"Hieron.: “Accordingly Aq. also rendered thus, _before his face shall go pestilence;_ Sym., _before his face shall death go first;_ the Fifth ed., _before his face shall death walk;_ the LXX and Theod. alone rendered _word_ for _death._”"},"1024.0.18":{"la":"Sic in textu Codd. 23, 62 (cum προσελ.), 86, 147.","en":"Thus in the text Codd. 23, 62 (with προσελ.), 86, 147."},"1024.0.19":{"la":"Hieron.: “Ubi diximus: _Egredietur diabolus ante pedes ejus_ . . . Aq. pro _diabolo_ transtulit _volatile;_ Sym. autem et Theod. et Quinta ed. _volucrem,_ quod Hebraice dicitur RESEPH.” Cf. Hex. ad Job. v. 4. Psal. lxxvii. 48. (In textu pro εἰς πεδία lectio εἰς παιδείαν est in Ald., Codd. 22, 36, 51, aliis, et Bar-Hebraeo apud Parsons., invitis Hieron. et Syro-hex.)","en":"Hieron.: “Where we said: _The devil shall go forth before his feet_ . . . Aq. for _devil_ rendered _flying thing;_ but Sym. and Theod. and the Fifth ed. _bird,_ which in Hebrew is called RESEPH.” Cf. Hex. on Job. v. 4. Psal. lxxvii. 48. (In the text, for εἰς πεδία the reading εἰς παιδείαν is in Ald., Codd. 22, 36, 51, and others, and in Bar-Hebraeus in Parsons, against Hieron. and Syro-hex.)"},"1024.0.20":{"la":"Sic in textu Codd. 23, 62, 86, 147.","en":"Thus in the text Codd. 23, 62, 86, 147."},"1024.0.21":{"la":"Sic in textu Codd. 62 (cum ἐξήκασεν), 86, 147. Cod. 23 om. διεθρύβη, et post αἱ νάπαι pergit αἱ ἐκ τοῦ αἰῶνος· αἱ ὁδοὶ αἱ ἐξ ἀρχῆς, omissis ceteris.","en":"Thus in the text Codd. 62 (with ἐξήκασεν), 86, 147. Cod. 23 omits διεθρύβη, and after αἱ νάπαι continues αἱ ἐκ τοῦ αἰῶνος· αἱ ὁδοὶ αἱ ἐξ ἀρχῆς, the rest being omitted."},"1024.0.22":{"la":"Sic in textu Codd. 23 (praem. ἀντὶ κόπων), 62 (cum Βαριὰμ pro Μαδιὰμ), 86, 147.","en":"Thus in the text Codd. 23 (prefixing ἀντὶ κόπων), 62 (with Βαριὰμ for Μαδιὰμ), 86, 147."},"1025.0.23":{"la":"Sic in textu Codd. 23 (cum τὸ ὅρμημά σου; κύριε, ἀνέβης), 62, 86 (sine σου posteriore), 147.","en":"Thus in the text Codd. 23 (with τὸ ὅρμημά σου; κύριε, ἀνέβης), 62, 86 (without the second σου), 147."},"1025.0.24":{"la":"Obelus est in Syro-hex.","en":"The obelus is in Syro-hex."},"1025.0.25":{"la":"Sic in textu Codd. 23 (cum τὰς βολ.), 62, 86, 147. Solus Nobil. e codice suo vetustissimo οὗ προέβης, et mox ἐχόρτασαν excitat.","en":"Thus in the text Codd. 23 (with τὰς βολ.), 62, 86, 147. Nobil. alone cites from his very ancient codex οὗ προέβης, and next ἐχόρτασαν."},"1025.0.26":{"la":"Sic in textu Codd. 23, 62, 86, 147.","en":"Thus in the text Codd. 23, 62, 86, 147."},"1025.0.27":{"la":"Hieron.: “Unde et ceteri interpretes, furorem volentes haereticum describere, transtulerunt: _Illisio_ [fortasse ἐντίναγμα, quod Aq. pro Hebraeo זֶרֶם posuit Jesai. xxxii. 2] vel _impetus_ [ὁρμὴ, s. ὅρμημα] _aquarum transiet._ Feruntur enim prono eloquentiae cursu, et praecipites, ut quemcunque obvium et levem invenerint, secum trahunt.” Qui locus antecessores nostros fugit.","en":"Hieron.: “Whence the other translators too, wishing to describe heretical fury, rendered: _The dashing_ [perhaps ἐντίναγμα, which Aq. put for the Hebrew זֶרֶם Jesai. xxxii. 2] or _onset_ [ὁρμὴ, or ὅρμημα] _of the waters shall pass over._ For they are borne along by the downhill course of their eloquence, and headlong, so that whatever light thing they find in their way they drag along with them.” This passage escaped our predecessors."},"1025.0.28":{"la":"Sic in textu Codd. 23 (om. σε, et cum μείζων in fine), 62 (cum μείζων), 86, 147 (cum μείζω).","en":"Thus in the text Codd. 23 (omitting σε, and with μείζων at the end), 62 (with μείζων), 86, 147 (with μείζω)."},"1025.0.29":{"la":"Syro-hex. ܐ. ܣ. ܕܪܘܡܚܐ[?] ܕܝܠܟ܀ ܬ. ܠܘܓܟܝܐ[?] ܕܝܠܟ܀","en":"Syro-hex. ܐ. ܣ. ܕܪܘܡܚܐ[?] ܕܝܠܟ܀ ܬ. ܠܘܓܟܝܐ[?] ܕܝܠܟ܀"},"1025.0.30":{"la":"Sic in textu Codd. 23 (cum μάχαιρα), 62, 86, 147.","en":"Thus in the text Codd. 23 (with μάχαιρα), 62, 86, 147."},"1025.0.31":{"la":"Sic Codd. 22, 51, alii, et Theodoret.","en":"Thus Codd. 22, 51, and others, and Theodoret."},"1025.0.32":{"la":"Sic in textu Codd. 23 (cum ἐγέρθης), 62, 86, 147.","en":"Thus in the text Codd. 23 (with ἐγέρθης), 62, 86, 147."},"1025.0.33":{"la":"Sic Comp., Ald., Codd. III, 22, 36, 40, alii, Hieron., Euseb., Syro-hex.","en":"Thus Comp., Ald., Codd. III, 22, 36, 40, and others, Hieron., Euseb., Syro-hex."},"1025.0.34":{"la":"Euseb. in Dem. Evang. p. 189, ubi in posteriori clausula male editum: εἰς σωτηρίαν λαοῦ σου σὺν Χριστῷ σου. Hieron.: “Sciendum autem, ut supra diximus, quod ubi posuerunt LXX plurali numero, _ut salvares Christos tuos,_ ibi esse in Hebraico, LAJESUA ETH MESSIACH; quod Aq. transtulit, _in salutem cum Christo tuo;_ non quod Deus egressus sit, ut salvaret populum, et salvaret Christum suum; sed quod in salutem populi venerit cum Christo suo . . . Sed et Quinta ed. similiter transtulit: _Egressus es in salutem populi tui, in salutem cum Christo tuo._”","en":"Euseb. in Dem. Evang. p. 189, where in the latter clause it is wrongly printed: εἰς σωτηρίαν λαοῦ σου σὺν Χριστῷ σου. Hieron.: “But it must be known, as we said above, that where the LXX put in the plural number, _that thou mightest save thine anointed ones,_ there is in the Hebrew LAJESUA ETH MESSIACH; which Aq. rendered, _for salvation with thine Anointed;_ not that God went forth to save the people and to save his Anointed; but that he came for the salvation of the people with his Anointed . . . And the Fifth ed. rendered similarly: _Thou wentest forth for the salvation of thy people, for salvation with thine Anointed._”"},"1025.0.35":{"la":"Hieron.: “Theod. autem, vere quasi pauper et Ebionita, sed et Sym. ejusdem dogmatis, pauperem sensum secuti, Judaice transtulerunt: _Egressus es in salutem populi tui, ut salvares Christum tuum;_ et: _Egressus es salvare populum tuum, salvare Christum tuum._ Rem incredibilem dicturus sum, sed tamen veram: isti semichristiani Judaice transtulerunt, et Judaeus Aquila interpretatus est, ut Christianus.”","en":"Hieron.: “But Theod., truly as a poor man and an Ebionite, and Sym. too, of the same doctrine, following a poor sense, rendered in Jewish fashion: _Thou wentest forth for the salvation of thy people, that thou mightest save thine Anointed;_ and: _Thou wentest forth to save thy people, to save thine Anointed._ I am about to say an incredible thing, but nevertheless true: these half-Christians rendered in Jewish fashion, and the Jew Aquila translated like a Christian.”"},"1026.0.36":{"la":"Hieron.: “Sexta editio prodens manifestissime sacramentum, ita vertit ex Hebraeo: _Egressus es ut salvares populum tuum per Jesum Christum tuum;_ quod Graece dicitur: ἐξῆλθες κ. τ. ἑ.","en":"Hieron.: “The Sixth edition, most plainly disclosing the mystery, renders thus from the Hebrew: _Thou wentest forth that thou mightest save thy people through Jesus thy Christ;_ which in Greek is said: ἐξῆλθες κ. τ. ἑ."},"1026.0.37":{"la":"Sic in textu Codd. 23 (cum χριστοὺς pro ἐκλεκτοὺς), 62, 86, 147.","en":"Thus in the text Codd. 23 (with χριστοὺς for ἐκλεκτοὺς), 62, 86, 147."},"1026.0.38":{"la":"Sic Ald., Codd. III (cum ἔβαλας), XII, 22, 26, 36, alii, Hieron., Syro-hex.","en":"Thus Ald., Codd. III (with ἔβαλας), XII, 22, 26, 36, and others, Hieron., Syro-hex."},"1026.0.39":{"la":"Prior lectio est in Comp. (cum εἰς τὸ τέλος), Ald., Codd. 22, 36, 51, aliis, Hieron.; posterior in Codd. 49, 95, aliis, Syro-hex. Hieron.: “_Sela,_ id est, _semper_ . . . Simulque considera quod ipsi LXX, rerum necessitate compulsi, qui semper _sela_ interpretabantur _diapsalma,_ nunc transtulerunt, _in finem._","en":"The former reading is in Comp. (with εἰς τὸ τέλος), Ald., Codd. 22, 36, 51, and others, Hieron.; the latter in Codd. 49, 95, and others, Syro-hex. Hieron.: “_Sela,_ that is, _always_ . . . And at the same time consider that the LXX themselves, who always rendered _sela_ by _diapsalma,_ now, compelled by the necessity of the matter, rendered, _to the end._"},"1026.0.40":{"la":"Hieron.: “Quod quidem et Theod. in bonam partem accipiens ait: _Ornasti_ [quasi ab עָדָה, _ornavit se_] _fundamentum usque ad collum._ Quinta ed.: _Denudasti,_ sive _evacuasti, fundamentum usque ad collum._”","en":"Hieron.: “Which indeed Theod. also, taking it in a good sense, says: _Thou hast adorned_ [as if from עָדָה, _he adorned himself_] _the foundation even to the neck._ The Fifth ed.: _Thou hast laid bare,_ or _emptied, the foundation even to the neck._”"},"1026.0.41":{"la":"Sic in textu Codd. 62, 86, 147. In Cod. 23 prior clausula desideratur.","en":"Thus in the text Codd. 62, 86, 147. In Cod. 23 the former clause is wanting."},"1026.0.42":{"la":"Cod. Coislin. apud Montef.","en":"Cod. Coislin. in Montef."},"1026.0.43":{"la":"Sic in textu Codd. 23 (cum τοῦ καταφυγεῖν πτωχοὺς), 62, 86, 147.","en":"Thus in the text Codd. 23 (with τοῦ καταφυγεῖν πτωχοὺς), 62, 86, 147."},"1026.0.44":{"la":"Sic Ald., Codd. III, XII, 22, 26, 36, alii, Hieron., Syro-hex.","en":"Thus Ald., Codd. III, XII, 22, 26, 36, and others, Hieron., Syro-hex."},"1026.0.45":{"la":"Sic in textu Codd. 23 (cum ἐπὶ τὰς θαλάσσας, et ἐταράχθησαν), 62, 86, 147 (cum τῆς θαλάσσης pro τῆς ἀβύσσου).","en":"Thus in the text Codd. 23 (with ἐπὶ τὰς θαλάσσας, and ἐταράχθησαν), 62, 86, 147 (with τῆς θαλάσσης for τῆς ἀβύσσου)."},"1026.0.46":{"la":"Sic Ald., Codd. 22, 36, 40, alii, et Syro-hex., qui in marg. affert: Ἀ. Σ. Θ. κοιλία (ܟܪܣܐ).","en":"Thus Ald., Codd. 22, 36, 40, and others, and Syro-hex., which in the margin cites: Ἀ. Σ. Θ. κοιλία (ܟܪܣܐ)."},"1026.0.47":{"la":"Sic Comp., Codd. 42, 106, alii. Hieron.: “_Et subter me conturbata est fortitudo mea;_ sive ut alibi scriptum reperimus, ἡ ἕξις μου, quod nos possumus dicere, _habitudo mea:_ diversa quippe exemplaria reperiuntur.” Syro-hex. ܡܢܝܢܐ ܕܝܠܝ, appicto Graeco ЄΞΙCΜΟΥ. Montef. non memorato auctore affert: Σ. Θ. καὶ ὑποκάτω μου ἐταράχθη ἡ ἕξις μου.","en":"Thus Comp., Codd. 42, 106, and others. Hieron.: “_And beneath me my strength was troubled;_ or, as we have found it written elsewhere, ἡ ἕξις μου, which we may call _my habit:_ for different copies are found.” Syro-hex. ܡܢܝܢܐ ܕܝܠܝ, with the Greek ЄΞΙCΜΟΥ attached. Montef., without naming his authority, cites: Σ. Θ. καὶ ὑποκάτω μου ἐταράχθη ἡ ἕξις μου."},"1026.0.48":{"la":"Sic in textu Codd. 23 (cum ὑπὸ τῆς φωνῆς . . . εἰς ἡμέραν θλίψεως, ἐπαγ. ἐφ’ ἑνὸς πολέμου τὸν λ. σ.), 62, 86, 147 (om. τρόμος).","en":"Thus in the text Codd. 23 (with ὑπὸ τῆς φωνῆς . . ."},"1027.0.49":{"la":"Sic Codd. III, XII (cum ἐπὶ φάτνης βόες), 26, 40 (cum ἐξ ἰάσεως), 153, 233 (cum αὐτῆς). Est duplex versio, ut videtur, Hebraei בָּרְפָתִים, et potior scriptura ἐξ ἰάσεως αὐτῶν, ut ad radicem רָפָה, _sanavit,_ referatur.","en":"Thus Codd. III, XII (with ἐπὶ φάτνης βόες), 26, 40 (with ἐξ ἰάσεως), 153, 233 (with αὐτῆς). It is, as it seems, a double version of the Hebrew בָּרְפָתִים, and the better spelling is ἐξ ἰάσεως αὐτῶν, so that it may be referred to the root רָפָה, _he healed._"},"1027.0.50":{"la":"Sic in textu Codd. 23, 62, 86, 147.","en":"Thus in the text Codd. 23, 62, 86, 147."},"1027.0.51":{"la":"Prior lectio est in Codd. 22 (cum εἰς συντέλειαν in marg. a prima m.), 51, 238; posterior in Codd. 95, 114, 185, et Theodoreto. Cf. Hex. ad Psal. xvii. 34.","en":"The former reading is in Codd. 22 (with εἰς συντέλειαν in the margin by the first hand), 51, 238; the latter in Codd. 95, 114, 185, and Theodoret. Cf. Hex. on Psal. xvii. 34."},"1027.0.52":{"la":"Sic in textu Codd. 23 (cum καθίσας pro ταχίσας), 62 (cum ἐπὶ τραχήλους), 86, 147 (cum ἐπιβέβηκα pro ἐπιβιβᾷ με). Ad ἀσφαλεῖς conferri potest S. Cyril. in XII Proph. p. 577 B: καὶ γοῦν Ἑβραίων ἡ ἔκδοσις ἀντὶ τῆς συντελείας τέθεικε τὴν ἀσφάλειαν [quasi pro Hebraeo אֱיָלוּת, _robur_].","en":"Thus in the text Codd. 23 (with καθίσας for ταχίσας), 62 (with ἐπὶ τραχήλους), 86, 147 (with ἐπιβέβηκα for ἐπιβιβᾷ με). On ἀσφαλεῖς may be compared S. Cyril. in XII Proph. p. 577 B: καὶ γοῦν Ἑβραίων ἡ ἔκδοσις ἀντὶ τῆς συντελείας τέθεικε τὴν ἀσφάλειαν [as if for the Hebrew אֱיָלוּת, _strength_]."}}};
